BEGIN;
SET search_path TO public;

-- Preguntas 901 a 1000
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (901, 'SUB-0901', 'SBM2', 'CONSTITUYE UN ÓRGANO DE DECISIÓN EN PRIMERA INSTANCIA POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES:', 'EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 39', '178105'),
    (902, 'SUB-0902', 'SBM2', '¿QUÉ SUCEDE CUANDO DENTRO DE UNA INVESTIGACIÓN POR INFRACCIONES GRAVES O MUY GRAVES SE IDENTIFICAN HECHOS QUE PUEDAN SER CONSIDERADOS COMO UNA INFRACCIÓN LEVE?', 'EL ÓRGANO DE INVESTIGACIÓN A CARGO LA INCLUIRÁ EN EL PROCEDIMIENTO DE INVESTIGACIÓN, SOLICITANDO LOS DESCARGOS CORRESPONDIENTES.', 'ART. 38', '178106'),
    (903, 'SUB-0903', 'SBM2', '¿DE QUIÉN ESTARÁ A CARGO LA OFICINA DE ASUNTOS INTERNOS?', 'ESTARÁ A CARGO DE UN PROFESIONAL CIVIL.', 'ART. 38', '178107'),
    (904, 'SUB-0904', 'SBM2', 'REALIZA INVESTIGACIONES EXTRAORDINARIAS DE OFICIO O POR DISPOSICIÓN DEL MINISTRO POR LA COMISIÓN DE INFRACCIONES GRAVES O MUY GRAVES, PREVIA EVALUACIÓN DE LA TRASCENDENCIA O GRAVEDAD DE LOS HECHOS A INVESTIGAR:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS.', 'ART. 38', '178108'),
    (905, 'SUB-0905', 'SBM2', 'REALIZA INVESTIGACIONES CUANDO SE ENCUENTRAN INVOLUCRADOS OFICIALES GENERALES DE LA POLICÍA NACIONAL DEL PERÚ:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS.', 'ART. 38', '178109'),
    (906, 'SUB-0906', 'SBM2', 'CONSTITUYE UN ÓRGANO DE INVESTIGACIÓN POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, CUANDO SE ENCUENTRAN INVOLUCRADOS OFICIALES GENERALES DE LA POLICÍA NACIONAL DEL PERÚ:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS.', 'ART. 38', '178110'),
    (907, 'SUB-0907', 'SBM2', 'CONSTITUYE UN ÓRGANO DE INVESTIGACIÓN POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS.', 'ART. 38', '178111'),
    (908, 'SUB-0908', 'SBM2', 'CONSTITUYE UN ÓRGANO DE INVESTIGACIÓN, REALIZAN INVESTIGACIONES ADMINISTRATIVO-DISCIPLINARIAS POR LA COMISIÓN DE INFRACCIONES MUY GRAVES, SEGÚN SU COMPETENCIA TERRITORIAL ASIGNADA:', 'LAS OFICINAS DE DISCIPLINA DE LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 38', '178112'),
    (909, 'SUB-0909', 'SBM2', '¿EN QUÉ CASOS EL SUPERIOR QUE CONOZCA DE UNA INFRACCIÓN DEBERÁ PONERLA EN CONOCIMIENTO INMEDIATO DEL ÓRGANO DE INVESTIGACIÓN QUE CORRESPONDA?', 'CUANDO EL SUPERIOR CONOZCA DE UNA INFRACCIÓN GRAVE O MUY GRAVE.', 'ART. 37', '178113'),
    (910, 'SUB-0910', 'SBM2', 'ES QUIÉN AL CONSTATAR O TOMAR CONOCIMIENTO DE LA COMISIÓN DE UNA INFRACCIÓN LEVE, IMPONDRÁ LA SANCIÓN QUE CORRESPONDA:', 'EL SUPERIOR DEL INVESTIGADO', 'ART. 37', '178114'),
    (911, 'SUB-0911', 'SBM2', 'ES EL MIEMBRO DE LA POLICÍA NACIONAL DEL PERÚ DE GRADO SUPERIOR AL INVESTIGADO:', 'SUPERIOR DEL INVESTIGADO.', 'ART. 37', '178115'),
    (912, 'SUB-0912', 'SBM2', 'EL SUPERIOR DEL INVESTIGADO, ES EL MIEMBRO DE LA POLICÍA NACIONAL DEL PERÚ DE GRADO SUPERIOR AL INVESTIGADO, O QUE SIENDO DEL MISMO GRADO LO TIENE BAJO SU:', 'COMANDO.', 'ART. 37', '178116'),
    (913, 'SUB-0913', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'OFICINA DE DISCIPLINA DE LAS REGIONES POLICIALES.', 'ART. 36', '178117'),
    (914, 'SUB-0914', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'OFICINA DE DISCIPLINA DE LOS FRENTES POLICIALES.', 'ART. 36', '178118'),
    (915, 'SUB-0915', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'INSPECTORÍAS DESCENTRALIZADAS.', 'ART. 36', '178119'),
    (916, 'SUB-0916', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'OFICINA DE DISCIPLINA (OD) DE LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, SEGÚN SU COMPETENCIA TERRITORIAL, A CARGO DE UN CORONEL DE ARMAS DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD; DE LAS DIRECCIONES.', 'ART. 36', '178120'),
    (917, 'SUB-0917', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 36', '178121'),
    (918, 'SUB-0918', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE UN ÓRGANO DISCIPLINARIO, A TRAVÉS DE:', 'INSPECTORÍA MACRO REGIONAL.', 'ART.36', '178122'),
    (919, 'SUB-0919', 'SBM2', 'ES UN ÓRGANO DISCIPLINARIO:', 'EL SUPERIOR JERÁRQUICO DEL INVESTIGADO.', 'ART. 36', '178123'),
    (920, 'SUB-0920', 'SBM2', 'ES UN ÓRGANO DISCIPLINARIO:', 'EL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 36', '178124'),
    (921, 'SUB-0921', 'SBM2', 'ES UN ÓRGANO DISCIPLINARIO:', 'LA OFICINA DE ASUNTOS INTERNOS. Ley N° 30714 - Régimen Disciplinario PNP', 'ART. 36', '178125'),
    (922, 'SUB-0922', 'SBM2', 'ES UN ÓRGANO DISCIPLINARIO:', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 36', '178126'),
    (923, 'SUB-0923', 'SBM2', 'TIENEN POR FINALIDAD INVESTIGAR O IMPONER SANCIONES, DE ACUERDO CON LO ESTABLECIDO EN LA PRESENTE LEY Y SU REGLAMENTO:', 'LOS ÓRGANOS DISCIPLINARIOS.', 'ART. 36', '178127'),
    (924, 'SUB-0924', 'SBM2', 'LA POTESTAD SANCIONADORA DISCIPLINARIA SE EJERCE EN EL MARCO DE LO ESTABLECIDO EN LA PRESENTE LEY, SUSTENTADO EN UN PROCEDIMIENTO:', 'ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 35', '178128'),
    (925, 'SUB-0925', 'SBM2', 'LA POTESTAD SANCIONADORA DISCIPLINARIA SE EJERCE EN EL MARCO DE LO ESTABLECIDO EN LA PRESENTE LEY, SUSTENTADO EN UN PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, Y ES ATRIBUIDO:', 'AL SUPERIOR, A LAS OFICINAS DE DISCIPLINA, A LAS INSPECTORÍAS DESCENTRALIZADAS, A LAS INSPECTORÍAS MACRO REGIONAL, AL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ Y AL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 35', '178129'),
    (926, 'SUB-0926', 'SBM2', 'SE EJERCE EN EL MARCO DE LO ESTABLECIDO EN LA PRESENTE LEY, SUSTENTADO EN UN PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, Y ES ATRIBUIDO AL SUPERIOR, A LAS OFICINAS DE DISCIPLINA, A LAS INSPECTORÍAS DESCENTRALIZADAS, A LAS INSPECTORÍAS MACRO REGIONAL, AL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ Y AL TRIBUNAL DE DISCIPLINA POLICIAL:', 'LA POTESTAD SANCIONADORA DISCIPLINARIA.', 'ART. 35', '178130'),
    (927, 'SUB-0927', 'SBM2', 'TIENEN LA OBLIGACIÓN DE COLABORAR CON LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO, BRINDANDO EN FORMA OPORTUNA, COMPLETA Y PRECISA, TODA LA INFORMACIÓN Y EL APOYO QUE LE SEA REQUERIDA:', 'EL PERSONAL POLICIAL DE LAS DIFERENTES UNIDADES DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 34', '178131'),
    (928, 'SUB-0928', 'SBM2', 'ES EL CONJUNTO DE ÓRGANOS DEL MINISTERIO DEL INTERIOR Y DE LA POLICÍA NACIONAL DEL PERÚ, QUE ACTÚAN INTEGRADOS EN MATERIA DE FISCALIZACIÓN, EVALUACIÓN, INVESTIGACIÓN Y SANCIÓN DISCIPLINARIA:', 'EL SISTEMA DISCIPLINARIO POLICIAL.', 'ART. 34', '178132'),
    (929, 'SUB-0929', 'SBM2', 'EL SISTEMA DISCIPLINARIO POLICIAL ES EL CONJUNTO DE ÓRGANOS DEL MINISTERIO DEL INTERIOR Y DE LA POLICÍA NACIONAL DEL PERÚ, QUE ACTÚAN INTEGRADOS EN MATERIA DE:', 'FISCALIZACIÓN, EVALUACIÓN, INVESTIGACIÓN Y SANCIÓN DISCIPLINARIA.', 'ART. 34', '178133'),
    (930, 'SUB-0930', 'SBM2', 'DEBE ESTAR DEBIDAMENTE MOTIVADO MEDIANTE UNA RELACIÓN CONCRETA Y DIRECTA DE LOS HECHOS PROBADOS Y LA EXPOSICIÓN DE LAS RAZONES JURÍDICAS Y NORMATIVAS, INDIVIDUALIZANDO AL INFRACTOR O INFRACTORES, LA TIPIFICACIÓN, LA SANCIÓN IMPUESTA Y SU DURACIÓN, SEGÚN CORRESPONDA:', 'EL ACTO O LA RESOLUCIÓN QUE DISPONE LA SANCIÓN DISCIPLINARIA.', 'ART. 33', '178134'),
    (931, 'SUB-0931', 'SBM2', 'LA RESOLUCIÓN DE SANCIÓN POR INFRACCIÓN GRAVE Y MUY GRAVE FIRME DEBIDAMENTE NOTIFICADA, SURTE EFECTO INMEDIATO POR SU PROPIA NATURALEZA, NO SIENDO NECESARIA LA EMISIÓN DE RESOLUCIÓN ADICIONAL ALGUNA. COPIA CERTIFICADA DE LA RESOLUCIÓN Y DEL CARGO DE RECEPCIÓN SERÁ REMITIDA A LA DIRECCIÓN EJECUTIVA DE PERSONAL, DENTRO DEL PLAZO DE:', '3 DÍAS HÁBILES', 'ART. 32', '178135'),
    (932, 'SUB-0932', 'SBM2', 'LA SANCIÓN POR INFRACCIÓN LEVE SE NOTIFICA DE INMEDIATO AL INFRACTOR Y SE REMITIRÁ A LA DIRECCIÓN EJECUTIVA DE PERSONAL DENTRO DEL PLAZO DE:', '3 DÍAS HÁBILES.', 'ART. 32', '178136'),
    (933, 'SUB-0933', 'SBM2', 'EL SUBORDINADO PODRÁ ACUDIR AL SUPERIOR INMEDIATO O A UNA INSTANCIA SUPERIOR CUANDO LAS SOLICITUDES SEAN NEGADAS O DEMORADAS INJUSTIFICADAMENTE POR EL SUPERIOR JERÁRQUICO A QUIEN SE RECURRIÓ. A ESTO SE LE DENOMINA:', 'EXCEPCIÓN DEL CONDUCTO REGULAR.', 'ART. 26', '178137'),
    (934, 'SUB-0934', 'SBM2', 'EL CONDUCTO REGULAR EXCEPCIONALMENTE PUEDE SER OBVIADO, CUANDO:', 'LAS SOLICITUDES SEAN NEGADAS O DEMORADAS INJUSTIFICADAMENTE POR EL SUPERIOR JERÁRQUICO A QUIEN SE RECURRIÓ.', 'ART. 26', '178138'),
    (935, 'SUB-0935', 'SBM2', 'NO PODRÁ CONTINUAR NI VOLVER A SER ASIGNADO AL CARGO QUE OCUPABA AL MOMENTO DE COMETER LA INFRACCIÓN O EN FUNCIONES ANÁLOGAS EN OTRA UNIDAD, POR UN PERÍODO DE 5 AÑOS:', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SANCIONADO CON RESOLUCIÓN FIRME POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE QUE AFECTE LA FUNCIÓN QUE VENÍA DESEMPEÑANDO.', 'ART. 13', '178139'),
    (936, 'SUB-0936', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SANCIONADO CON RESOLUCIÓN FIRME POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE QUE AFECTE LA FUNCIÓN QUE VENÍA DESEMPEÑANDO, NO PODRÁ CONTINUAR NI VOLVER A SER ASIGNADO AL CARGO QUE OCUPABA AL MOMENTO DE COMETER LA INFRACCIÓN O EN FUNCIONES ANÁLOGAS EN OTRA UNIDAD, POR UN PERÍODO DE:', '5 AÑOS.', 'ART. 13', '178140'),
    (937, 'SUB-0937', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SANCIONADO CON RESOLUCIÓN FIRME POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE QUE AFECTE LA FUNCIÓN QUE VENÍA DESEMPEÑANDO, NO PODRÁ CONTINUAR NI VOLVER A SER ASIGNADO AL CARGO QUE OCUPABA AL MOMENTO DE COMETER LA INFRACCIÓN O EN FUNCIONES ANÁLOGAS EN OTRA UNIDAD, POR UN PERÍODO DE 5 AÑOS. ¿QUIÉN REALIZARÁ LAS ACCIONES NECESARIAS PARA SU CUMPLIMIENTO?', 'LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 13', '178141'),
    (938, 'SUB-0938', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SANCIONADO CON RESOLUCIÓN FIRME POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE QUE AFECTE LA FUNCIÓN QUE VENÍA DESEMPEÑANDO, NO PODRÁ CONTINUAR NI VOLVER A SER ASIGNADO AL CARGO QUE OCUPABA AL MOMENTO DE COMETER LA INFRACCIÓN O EN FUNCIONES ANÁLOGAS EN OTRA UNIDAD, POR UN PERÍODO DE 5 AÑOS. EL PÁRRAFO ANTERIOR SE ENCUENTRA EN EL CAPÍTULO 3 - NORMAS DE CONDUCTA, REFERIDA A:', 'IMPEDIMENTO EN EL DESEMPEÑO DEL CARGO.', 'ART. 13', '178142'),
    (939, 'SUB-0939', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, ESTÁ PROHIBIDO DE:', 'USAR SU PROFESIÓN CONTRA LOS INTERESES DE LA INSTITUCIÓN POLICIAL.', 'ART. 12', '178143'),
    (940, 'SUB-0940', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, ESTÁ PROHIBIDO DE:', 'PARTICIPAR EN ACTOS DE PETICIÓN EN CONJUNTO.', 'ART. 12', '178144'),
    (941, 'SUB-0941', 'SBM2', 'CUANDO ALGÚN MIEMBRO DE LA POLICÍA NACIONAL DEL PERÚ, EN SITUACIÓN DE DISPONIBILIDAD O RETIRO, SE CONSIDERE AFECTADO POR UNA CONDUCTA QUE CONSTITUYA INFRACCIÓN COMETIDA POR OTRO MIEMBRO DE LA INSTITUCIÓN EN SITUACIÓN DE ACTIVIDAD O DISPONIBILIDAD:', 'PODRÁ SOLICITAR LA INVESTIGACIÓN O SANCIÓN CORRESPONDIENTE, MEDIANTE DENUNCIA DEBIDAMENTE FUNDAMENTADA ANTE EL SUPERIOR, DEPENDENCIA DE LA INSPECTORÍA GENERAL MÁS CERCANA U ÓRGANO DE DISCIPLINARIO COMPETENTE.', 'ART. 10', '178145'),
    (942, 'SUB-0942', 'SBM2', 'OBEDECERÁ LAS ÓRDENES RECIBIDAS SIEMPRE QUE NO SEAN CONTRARIAS A LO SEÑALADO EN LA CONSTITUCIÓN POLÍTICA DEL PERÚ Y LA NORMATIVIDAD VIGENTE Y DARÁ CUENTA DE SU CUMPLIMIENTO AL SUPERIOR QUE LAS IMPARTIÓ. EL PÁRRAFO ANTERIOR ESTA DENTRO DEL CAPÍTULO DENOMINADO NORMAS DE CONDUCTA, REFERIDO A:', 'RESPONSABILIDAD DEL SUBORDINADO.', 'ART. 9', '178146'),
    (943, 'SUB-0943', 'SBM2', 'EL SUPERIOR, ES EL RESPONSABLE DE EJERCER AUTORIDAD EN TODO LUGAR Y CIRCUNSTANCIA, ASÍ COMO:', 'MANTENER LA DISCIPLINA MEDIANTE LA INSTRUCCIÓN, EL MANDO JUSTO, EL BUEN EJEMPLO Y LA IMPARCIALIDAD. ESTIMULA Y CORRIGE OPORTUNAMENTE AL SUBORDINADO DENTRO DEL MARCO LEGAL.', 'ART. 8', '178147'),
    (944, 'SUB-0944', 'SBM2', 'ES EL CONJUNTO DE PRINCIPIOS, VALORES Y NORMAS DE CONDUCTA QUE REGULA EL COMPORTAMIENTO DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'ÉTICA POLICIAL.', 'ART. 5', '178148'),
    (945, 'SUB-0945', 'SBM2', 'CONTIENE LOS PRINCIPIOS RECTORES, LOS BIENES JURÍDICOS PROTEGIDOS, LAS NORMAS DE DISCIPLINA Y SERVICIO, LA TIPIFICACIÓN DE LAS INFRACCIONES, LAS SANCIONES DISCIPLINARIAS, LA ESTRUCTURA Y COMPETENCIAS DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO POLICIAL Y EL PROCEDIMIENTO SANCIONADOR. NOS REFERIMOS A ...:', 'EL CONTENIDO DE LA LEY 30714.', 'ART. 3', '178149'),
    (946, 'SUB-0946', 'SBM2', 'ES LA FACULTAD QUE TIENE EL SUPERIOR PARA IMPARTIR ÓRDENES Y DISPOSICIONES A UN SUBORDINADO EN EL EJERCICIO DEL CARGO ASIGNADO POR NOMBRAMIENTO EXPRESO:', 'EL COMANDO.', 'ART. 20', '178150'),
    (947, 'SUB-0947', 'SBM2', 'EL SUBORDINADO AL DIRIGIRSE AL SUPERIOR DEBE ANTEPONER LA PALABRA "MI", SEGUIDA DEL GRADO QUE OSTENTA EL SUPERIOR. EL TRATO DE "USTED" ES OBLIGATORIO ENTRE EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN TODOS LOS ACTOS PÚBLICOS Y PRIVADOS. EL SUPERIOR DEBE RESPONDER CON RESPETO Y CONSIDERACIÓN. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178151'),
    (948, 'SUB-0948', 'SBM2', 'ES LA REPRESENTACIÓN ANTE LA OPINIÓN PÚBLICA DEL ACCIONAR DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'IMAGEN INSTITUCIONAL.', 'ART. 5', '178152'),
    (949, 'SUB-0949', 'SBM2', 'CONSTITUYE LA BASE PRINCIPAL DE LA RELACIÓN DE CONFIANZA Y LEGITIMIDAD QUE DEBE IMPERAR ENTRE LA INSTITUCIÓN, SU PERSONAL Y LA SOCIEDAD EN GENERAL, CONSTRUIDA SOBRE UNA SÓLIDA DISCIPLINA Y UN SERVICIO EFICIENTE Y OPORTUNO:', 'IMAGEN INSTITUCIONAL.', 'ART. 5', '178153'),
    (950, 'SUB-0950', 'SBM2', 'ES LA CONDICIÓN ESENCIAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'DISCIPLINA POLICIAL.', 'ART. 5', '178154'),
    (951, 'SUB-0951', 'SBM2', 'SE ENTIENDE COMO EL ACATAMIENTO CONSCIENTE Y VOLUNTARIO DE LAS ÓRDENES QUE SE DICTAN CON ARREGLO A LEY, QUE PERMITE ASEGURAR LA UNIDAD DE ACCIÓN Y EL CUMPLIMIENTO DE LA FINALIDAD FUNDAMENTAL, MISIÓN Y FUNCIONES INSTITUCIONALES:', 'DISCIPLINA POLICIAL.', 'ART. 5', '178155'),
    (952, 'SUB-0952', 'SBM2', 'NO SE PODRÁ INVESTIGAR O IMPONER DOS O MÁS SANCIONES DISCIPLINARIAS POR EL MISMO HECHO, EN LOS CASOS QUE SE APRECIE LA IDENTIDAD DEL SUJETO, HECHO Y FUNDAMENTO. CORRESPONDE AL PRINCIPIO DE:', 'PROHIBICIÓN DE LA DOBLE INVESTIGACIÓN O SANCIÓN.', 'ART. 1', '178156'),
    (953, 'SUB-0953', 'SBM2', 'LAS DECISIONES EN EL EJERCICIO DE LA POTESTAD DISCIPLINARIA SANCIONADORA, DEBEN MANTENER PROPORCIÓN ENTRE LA INFRACCIÓN COMETIDA Y LA SANCIÓN: SE REFIERE AL:', 'PRINCIPIO DE PROPORCIONALIDAD.', 'ART.1', '178157'),
    (954, 'SUB-0954', 'SBM2', 'GARANTIZA LOS DERECHOS DE IMPUGNACIÓN Y DE CONTRADICCIÓN MEDIANTE UNA ESTRUCTURA JERÁRQUICA QUE PERMITE LA PARTICIPACIÓN DE UNA AUTORIDAD INDEPENDIENTE, IMPARCIAL EN LA REVISIÓN DE UN ACTO DISCIPLINARIO PREVIO, SEA PORQUE LOS INTERESADOS INTERPUSIERON RECURSOS DE APELACIÓN O PROCEDA LA CONSULTA:', 'LA DOBLE INSTANCIA.', 'ART. 1', '178158'),
    (955, 'SUB-0955', 'SBM2', 'LA FACULTAD PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO PARA LA DETERMINACIÓN DE LA EXISTENCIA DE INFRACCIONES DISCIPLINARIAS TIPIFICADAS EN LA PRESENTE LEY, PRESCRIBE POR EL TRANSCURSO DE LOS SIGUIENTES PLAZOS:', 'POR INFRACCIONES LEVES, A LOS SEIS MESES DE COMETIDAS, O TRANSCURRIDO DIECIOCHO MESES, CUANDO HUBIESEN SIDO DETECTADAS EN EL CURSO DE UN PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE.', 'ART. 68', '178159'),
    (956, 'SUB-0956', 'SBM2', 'ES UNA MEDIDA PREVENTIVA QUE SOLAMENTE PUEDE SER IMPUESTA, MEDIANTE RESOLUCIÓN DEBIDAMENTE MOTIVADA, EN LOS PROCEDIMIENTOS ADMINISTRATIVO-DISCIPLINARIOS SUMARIOS O EN LOS CASOS DONDE SE INVESTIGAN INFRACCIONES MUY GRAVES QUE SE SANCIONAN CON PASE A LA SITUACIÓN DE RETIRO.', 'SUSPENSIÓN TEMPORAL DEL SERVICIO.', 'ART. 79 Ley N° 30714 - Régimen Disciplinario PNP', '178160'),
    (957, 'SUB-0957', 'SBM2', 'SE EJECUTA CUANDO LA PERMANENCIA EN UN DETERMINADO CARGO DEL PRESUNTO INFRACTOR PUEDA PONER EN RIESGO EL DESARROLLO DEL PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO. SU EJECUCIÓN SE HARÁ EFECTIVA AUTOMÁTICAMENTE Y EN NINGÚN CASO ESTA MEDIDA IMPLICARÁ QUE EL SERVIDOR AFECTADO DEJE DE PERCIBIR LOS HABERES A QUE TIENE DERECHO. NOS REFERIMOS A ...:', 'SEPARACIÓN TEMPORAL DEL CARGO', 'ART. 74', '178161'),
    (958, 'SUB-0958', 'SBM2', 'SEÑALE UNA MEDIDA PREVENTIVA:', 'SEPARACIÓN TEMPORAL DEL CARGO.', 'ART. 74', '178162'),
    (959, 'SUB-0959', 'SBM2', 'NO CONSTITUYEN DEMÉRITO NI SANCIÓN ADMINISTRATIVA', 'CESE TEMPORAL DEL EMPLEO.', 'ART. 73', '178163'),
    (960, 'SUB-0960', 'SBM2', 'LA SANCIÓN DE RIGOR SE EXTIENDE DE:', 'UNO A 15 DÍAS.', 'ART. 30', '178164'),
    (961, 'SUB-0961', 'SBM2', 'SON MEDIDAS DISCIPLINARIAS ESCRITAS QUE SE IMPONEN LUEGO DE SEGUIRSE EL DEBIDO PROCEDIMIENTO COMO CONSECUENCIA DE UNA CONDUCTA QUE CONSTITUYE INFRACCIÓN PREVISTA EN LA PRESENTE NORMA:', 'LAS SANCIONES.', 'ART. 29', '178165'),
    (962, 'SUB-0962', 'SBM2', 'CONSTITUYE UNA CLASE DE SANCIÓN:', 'AMONESTACIÓN.', 'ART. 30 Ley N° 30714 - Régimen Disciplinario PNP', '178166'),
    (963, 'SUB-0963', 'SBM2', 'CONSTITUYE UNA CLASE DE SANCIÓN:', 'SIMPLE.', 'ART. 30', '178167'),
    (964, 'SUB-0964', 'SBM2', 'CONSTITUYE UNA CLASE DE SANCIÓN:', 'RIGOR.', 'ART. 30', '178168'),
    (965, 'SUB-0965', 'SBM2', 'CONSTITUYE UNA CLASE DE SANCIÓN:', 'PASE A LA SITUACIÓN DE DISPONIBILIDAD POR MEDIDA DISCIPLINARIA.', 'ART. 30', '178169'),
    (966, 'SUB-0966', 'SBM2', 'CONSTITUYE UNA CLASE DE SANCIÓN:', 'PASE A LA SITUACIÓN DE RETIRO POR MEDIDA DISCIPLINARIA.', 'ART. 30', '178170'),
    (967, 'SUB-0967', 'SBM2', 'CONSTITUYE UNA CLASE DE INFRACCIÓN:', 'LEVE', 'ART. 28', '178171'),
    (968, 'SUB-0968', 'SBM2', 'SE EJERCE MANTENIENDO A CADA CUÁL EN EL ÁMBITO DE SUS DEBERES Y DERECHOS:', 'SUBORDINACIÓN.', 'ART. 16', '178172'),
    (969, 'SUB-0969', 'SBM2', 'SE DETERMINA POR LA FECHA DEL ÚLTIMO ASCENSO; A IGUALDAD DE ESTE, POR LA DE ASCENSO AL GRADO ANTERIOR; Y ASÍ SUCESIVAMENTE: Ley N° 30714 - Régimen Disciplinario PNP', 'LA ANTIGÜEDAD EN EL GRADO.', 'ART. 17', '178173'),
    (970, 'SUB-0970', 'SBM2', 'EN TODO LO CONCERNIENTE A LOS ACTOS DEL SERVICIO, EL MAYOR GRADO PREVALECE SOBRE EL MENOR. A IGUALDAD DE GRADO, LA MAYOR ANTIGÜEDAD CONFIERE PRELACIÓN SOBRE LA MENOR. EN IGUALDAD DE GRADO Y ANTIGÜEDAD, EL OFICIAL DE ARMAS PRECEDE AL DE SERVICIOS Y ESTE AL DE ESTATUS DE OFICIAL, ASIMISMO, EL SUBOFICIAL DE ARMAS PRECEDE AL DE SERVICIOS. LA ASIGNACIÓN DE PERSONAL A LOS CARGOS SE SUJETA A ESTOS. EL PÁRRAFO ANTERIOR CONSTITUYE:', 'CRITERIOS DE PRELACIÓN.', 'ART. 18', '178174'),
    (971, 'SUB-0971', 'SBM2', 'SE IMPULSARÁ DE OFICIO EL PROCEDIMIENTO ADMINISTRATIVO - DISCIPLINARIO. CORRESPONDE AL PRINCIPIO DE:', 'CELERIDAD.', 'ART. 1', '178175'),
    (972, 'SUB-0972', 'SBM2', 'LAS SANCIONES PREVISTAS EN LA PRESENTE NORMA SE GRADÚAN EN ATENCIÓN A LA GRAVEDAD, NATURALEZA O TRASCENDENCIA DEL HECHO, ASÍ COMO LAS REFERENCIAS ADMINISTRATIVAS DISCIPLINARIAS DEL INFRACTOR. CORRESPONDE LA PRINCIPIO DE:', 'RAZONABILIDAD.', 'ART. 1', '178176'),
    (973, 'SUB-0973', 'SBM2', 'EL DERECHO A LA DEFENSA, CORRESPONDE AL:', 'PRINCIPIO DEL DEBIDO PROCEDIMIENTO.', 'ART. 1', '178178'),
    (974, 'SUB-0974', 'SBM2', 'LAS INFRACCIONES SON SANCIONADAS CON SUJECIÓN A LOS PROCEDIMIENTOS ESTABLECIDOS EN LA PRESENTE NORMA, RESPETÁNDOSE LAS GARANTÍAS Y DERECHOS DEL DEBIDO PROCEDIMIENTO. NOS REFERIMOS AL:', 'PRINCIPIO DEL DEBIDO PROCEDIMIENTO.', 'ART. 1', '178179'),
    (975, 'SUB-0975', 'SBM2', 'EL SUPERIOR Y LOS ÓRGANOS DISCIPLINARIOS DEBEN ACTUAR CON RESPETO A LA CONSTITUCIÓN POLÍTICA DEL PERÚ, LA LEY Y AL DERECHO, DENTRO DE LAS FACULTADES QUE LE ESTÉN ATRIBUIDAS, Y DE ACUERDO CON LOS FINES PARA LOS QUE LES FUERON CONFERIDAS. NOS REFERIMOS AL PRINCIPIO DE:', 'PRINCIPIO DE LEGALIDAD.', 'ART. 1', '178180'),
    (976, 'SUB-0976', 'SBM2', 'PARA CASOS COMPLEJOS, LA ETAPA DE INVESTIGACIÓN PARA LAS INFRACCIONES MUY GRAVES SERÁ DE ...:', '50 DÍAS HÁBILES.', 'ART. 66', '178181'),
    (977, 'SUB-0977', 'SBM2', 'LA ETAPA DE INVESTIGACIÓN EN EL PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO SUMARIO TIENE UN PLAZO MÁXIMO DE ...:', 'DIEZ DÍAS HÁBILES.', 'ART. 67', '178182'),
    (978, 'SUB-0978', 'SBM2', 'ES COMPETENTE A NIVEL NACIONAL PARA REALIZAR INVESTIGACIONES EXTRAORDINARIAS POR LA COMISIÓN DE INFRACCIONES DISCIPLINARIAS GRAVES O MUY GRAVES:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS.', 'ART. 45', '178183'),
    (979, 'SUB-0979', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ NO PODRÁ AUSENTARSE DEL ÁMBITO DE LA DEMARCACIÓN POLICIAL ...:', 'SIN CONOCIMIENTO PREVIO DE SU COMANDO.', 'ART. 14', '178184'),
    (980, 'SUB-0980', 'SBM2', 'LA RECOPILACIÓN DE LAS INFORMACIONES QUE PERMITAN EL ESCLARECIMIENTO DE LOS HECHOS; CONSTITUYE:', 'UNA DE LAS ACCIONES PREVIAS QUE PUEDEN REALIZARSE PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 50', '178185'),
    (981, 'SUB-0981', 'SBM2', 'OBJETIVOS.- PROMOVER LA INVESTIGACIÓN E INNOVACIÓN DE LOS CONTENIDOS QUE IMPARTE, GARANTIZANDO LA ACTUALIZACIÓN CONSTANTE Y LA CALIDAD DE SU:', 'OFERTA EDUCATIVA.', 'ART. 6. Lit. d', '181504'),
    (982, 'SUB-0982', 'SBM2', 'DOCENTES.- CONFORME A LAS DISPOSICIONES DEL REGLAMENTO, PUEDEN EJERCER LA DOCENCIA:', 'LOS DIRECTIVOS Y MIEMBROS DE LOS CONSEJOS DE LA ESCUELA.', 'ART. 10', '181505'),
    (983, 'SUB-0983', 'SBM2', 'INVESTIGACIÓN.- LA FORMACIÓN PROFESIONAL POLICIAL, PROMUEVE LA INVESTIGACIÓN E INNOVACIÓN EN LAS ÁREAS DEL CONOCIMIENTO QUE FORMAN PARTE DE SUS:.', 'PROGRAMAS ACADÉMICOS', 'ART. 16', '181506'),
    (984, 'SUB-0984', 'SBM2', 'CONVALIDACIÓN Y REVALIDACIÓN.- DE ACUERDO AL PROCEDIMIENTO ESTABLECIDO EN EL REGLAMENTO Y CON OPINIÓN PREVIA DEL CONSEJO ACADÉMICO, LA CONVALIDACIÓN ACADÉMICA SE AUTORIZA MEDIANTE RESOLUCIÓN DEL:.', 'DIRECTOR DE LA ESCUELA RESPECTIVA.', 'ART. 21', '181507'),
    (985, 'SUB-0985', 'SBM2', 'ES UN PRINCIPIO DE LA FORMACION PROFESIONAL POLICIAL:', 'DESARROLLO DE COMPETENCIAS PERTINENTES.', 'ART. 5', '181508'),
    (986, 'SUB-0986', 'SBM2', 'ES PRINCIPIO DE LA FORMACION PROFESIONAL POLICIAL:', 'INVESTIGACION E INNOVACION.', 'ART. 5', '181509'),
    (987, 'SUB-0987', 'SBM2', 'SON LOS QUE CUMPLEN TODOS LOS REQUISITOS SEÑALADOS EN LAS NORMAS QUE REGULAN LOS PROCESOS DE ADMISIÓN, SUPERAN SATISFACTORIAMENTE SUS ETAPAS DE SELECCIÓN Y SE ENCUENTRAN MATRICULADOS EN ALGUNA DE ELLAS:', 'ESTUDIANTES DE LAS ESCUELAS DE LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 11', '181510'),
    (988, 'SUB-0988', 'SBM2', 'NO PUEDE RESTRINGIRSE O RETIRARSE LA CONDICION DE ESTUDIANTE POR HECHOS VINCULADOS A:', 'PATERNIDAD', 'ART. 11', '181511'),
    (989, 'SUB-0989', 'SBM2', 'EL CONSEJO ACADÉMICO SUPERIOR Y EL CONSEJO DISCIPLINARIO SUPERIOR CONSTITUYEN:', 'SEGUNDA INSTANCIA', 'ART. 22', '181512'),
    (990, 'SUB-0990', 'SBM2', 'NO ES UNA CAUSAL DE SEPARACIÓN PARA ESTUDIANTES DE PREGRADO DE LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ:', 'PARTICIPAR EN LA ALTERACIÓN DEL ORDEN INTERNO', 'ART. 24', '181513'),
    (991, 'SUB-0991', 'SBM2', 'NO ES UNA CAUSAL DE SEPARACIÓN PARA ESTUDIANTES DE PREGRADO DE LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ:', 'NO HABER OBTENIDO NOTA APROBATORIA MÍNIMA DE 13 EN CUALQUIERA DE LAS ASIGNATURAS O EN EL PROMEDIO GENERAL.', 'ART. 24', '181514'),
    (992, 'SUB-0992', 'SBM2', 'ES UNA CAUSAL DE BAJA:', 'LA CULMINACIÓN SATISFACTORIA DEL PLAN DE ESTUDIOS ACADÉMICO Y EL FACTOR DISCIPLINARIO, INCLUYENDO NO ENCONTRARSE SOMETIDO A PROCESO DE INVESTIGACIÓN O JUDICIAL CONFORME SE DISPONGA EN EL REGLAMENTO', 'ART. 25', '181515'),
    (993, 'SUB-0993', 'SBM2', 'LOS ESTUDIANTES QUE SEAN SANCIONADOS CON EXPULSIÓN :', 'DEBEN SUFRAGAR LOS GASTOS IRROGADOS AL ESTADO', 'ART. 23', '181516'),
    (994, 'SUB-0994', 'SBM2', 'LA ORGANIZACIÓN Y FUNCIONAMIENTO DE LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ DE ACUERDO A:', 'A SU NATURALEZA Y AUTONOMÍA ACADÉMICA, DISCIPLINARIA Y ADMINISTRATIVA.', 'ART. 8', '181517'),
    (995, 'SUB-0995', 'SBM2', 'PARA ACCEDER A BECAS DE ESTUDIO, EN EL PAÍS O EN EL EXTRANJERO, Y PARTICIPAR EN LOS PROGRAMAS EQUIVALENTES DE PREGRADO Y POSGRADO SE REQUIERE PREVIAMENTE:', 'HABER LOGRADO VACANTES EN LOS PROCESOS DE ADMISIÓN.', 'ART. 13', '181518'),
    (996, 'SUB-0996', 'SBM2', 'LOS PROGRAMAS DE ESTUDIO SON APROBADOS POR:', 'DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ', 'ART. 15', '181519'),
    (997, 'SUB-0997', 'SBM2', 'LA EVALUACIÓN ES INTEGRAL Y CONTINUA DESTINADA A ESTIMULAR Y DESARROLLAR LAS CAPACIDADES, APTITUDES Y ACTITUDES CRÍTICAS Y CREATIVAS EN:', 'LOS ESTUDIANTES.', 'ART. 17 Decreto Legislativo N° 1318 - Ley que Regula la Formación Profesional de la PNP y Reglamento', '181520'),
    (998, 'SUB-0998', 'SBM2', 'SON GRADUADOS DE LAS ESCUELAS DE LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ LOS ESTUDIANTES QUE HAYAN CONCLUIDO SATISFACTORIAMENTE:', 'SU PLAN CURRICULAR Y COMPLETADO LOS CRÉDITOS EDUCATIVOS', 'ART. 18', '181521'),
    (999, 'SUB-0999', 'SBM2', 'LA CONVALIDACIÓN ACADÉMICA SE AUTORIZA MEDIANTE RESOLUCIÓN DEL DIRECTOR DE LA:', 'ESCUELA RESPECTIVA.', 'ART. 21', '181522'),
    (1000, 'SUB-1000', 'SBM2', 'ES CAUSAL DE BAJA:', 'POR FALLECIMIENTO.', 'ART. 25', '181523')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

