    (1050, 'SUB-1050', 'SBM2', 'A QUIEN CORRESPONDE EL SIGUIENTE ENUNCIADO: EL ESTUDIANTE SEA EXPULSADO POR MEDIDA DISCIPLINARIA O SEPARADO POR INSUFICIENCIA ACADÉMICA O A SU SOLICITUD, LA ENFPP HARÁ EFECTIVO EL COBRO DE LA OBLIGACIÓN ECONÓMICA DE MANERA PROPORCIONAL AL TIEMPO DE PERMANENCIA Y LOS RECURSOS EMPLEADOS EN EL PROCESO DE FORMACIÓN PROFESIONAL POLICIAL:.', 'OBLIGACIÓN ECONÓMICA', 'REGLAMENTO ART. 93', '181580'),
    (1051, 'SUB-1051', 'SBM2', 'ES PARTE DE LA ESTRUCTURA ORGÁNICA DE LAS UNIDADES ACADÉMICAS DE FORMACIÓN PREGRADO PARA EL CUMPLIMIENTO DE SUS FINES, OBJETIVOS Y FUNCIONES:.', 'DIRECCIÓN', 'REGLAMENTO ART. 52', '181581'),
