    (1053, 'SUB-1053', 'SBM2', 'LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ ES EL ÓRGANO DE GESTIÓN ACADÉMICA Y ADMINISTRATIVA ENCARGADA DE:.', 'LOS PROCESOS EDUCATIVOS DE LOS ESTUDIANTES Y PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 7', '181583'),
    (1054, 'SUB-1054', 'SBM2', 'CONFORME A LA NORMATIVIDAD VIGENTE, EL OFICIAL SUPERIOR DE ARMAS QUE SE ENCUENTRA A CARGO EN LA ESCUELA DE FORMACIÓN CONTINUA, ES DESIGNADO MEDIANTE:.', 'RESOLUCIÓN MINISTERIAL', 'REGLAMENTO ART. 56', '181584'),
    (1055, 'SUB-1055', 'SBM2', 'ES UNA CAUSAL DE SEPARACIÓN:', 'NO SOLICITAR REINCORPORACIÓN LUEGO DEL PERÍODO DE GRAVIDEZ, CONFORME AL REGLAMENTO.', 'ART. 24', '181585'),
