    (1057, 'SUB-1057', 'SBM2', 'QUE PRINCIPIO NO CORRESPONDE A LA FORMACION PROFESIONAL POLICIAL', 'INVESTIGACION, TECNICA Y CIENTIFICA', 'ART. 5', '181587'),
