    (1059, 'SUB-1059', 'SBM2', 'LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ ES EL ÓRGANO DE GESTIÓN ACADÉMICA Y ADMINISTRATIVA ENCARGADA DE LOS PROCESOS EDUCATIVOS DE LOS ESTUDIANTES Y:', 'PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 7', '181589'),
    (1060, 'SUB-1060', 'SBM2', 'ORGANIZACIÓN Y FUNCIONAMIENTO. LA DIRECCIÓN DE EDUCACIÓN Y DOCTRINA DE LA POLICÍA NACIONAL DEL PERÚ TIENEN UN CONSEJO SUPERIOR DE FORMACION PROFESIONAL COMO:', 'ÓRGANO MÁXIMO', 'ART. 8', '181590'),
    (1061, 'SUB-1061', 'SBM2', 'RESPECTO A LA DENEGATORIA DE ACCESO A LA INFORMACIÓN PÚBLICA; CUANDO UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA NO LOCALIZA INFORMACIÓN QUE ESTÁ OBLIGADA A POSEER O CUSTODIAR, DEBERÁ:', 'ACREDITAR QUE HA AGOTADO LAS ACCIONES NECESARIAS PARA OBTENERLA A FIN BRINDAR UNA RESPUESTA AL SOLICITANTE.', 'ART. 13', '186276'),
    (1062, 'SUB-1062', 'SBM2', 'LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA A LA CUAL SE SOLICITE INFORMACIÓN NO PODRÁ NEGAR LA MISMA BASANDO SU DECISIÓN EN:', 'LA IDENTIDAD DEL SOLICITANTE.', 'ART. 13', '186277'),
    (1063, 'SUB-1063', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA. INDIQUE, ¿QUÉ PLAZO TIENE LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA A LA CUÁL SE HAYA PRESENTADO LA SOLICITUD DE INFORMACIÓN, PARA OTORGARLA?', 'DEBE OTORGARLA EN UN PLAZO NO MAYOR DE 10 DÍAS HÁBILES.', 'ART. 11', '186278'),
    (1064, 'SUB-1064', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, DE NO MEDIAR RESPUESTA EN EL PLAZO PREVISTO, EL SOLICITANTE PUEDE CONSIDERAR:', 'DENEGADO SU PEDIDO', 'ART. 11', '186279'),
    (1065, 'SUB-1065', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, ¿QUÉ PLAZO TIENE EL SOLICITANTE PARA INTERPONER RECURSO DE APELACIÓN LUEGO DE QUE SU SOLICITUD HA SIDO DENEGADA?', 'EN UN PLAZO NO MAYOR DE 15 DÍAS CALENDARIO.', 'ART. 11', '186280'),
    (1066, 'SUB-1066', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, ¿QUÉ PLAZO TIENE EL EL TRIBUNAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA PARA RESOLVER EL RECURSO DE APELACIÓN, ANTE LA DENEGATORIA DE LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA A ENTREGAR LA INFORMACIÓN SOLICITADA?', '10 DÍAS HÁBILES.', 'ART. 11', '186282'),
    (1067, 'SUB-1067', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, ¿QUÉ SUCEDE CUANDO EL TRIBUNAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA NO RESUELVE EL RECURSO DE APELACIÓN EN EL PLAZO MÁXIMO DE 10 DÍAS HÁBILES, ANTE LA DENEGATORIA DE LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA A ENTREGAR LA INFORMACIÓN SOLICITADA?', 'EL SOLICITANTE PODRÁ DAR POR AGOTADA LA VÍA ADMINISTRATIVA', 'ART. 11', '186283'),
    (1068, 'SUB-1068', 'SBM2', '¿QUIÉNES ESTÁN OBLIGADAS A INFORMAR SOBRE LAS CARACTERÍSTICAS DE LOS SERVICIOS PÚBLICOS QUE PRESTA, SUS TARIFAS Y SOBRE LAS FUNCIONES ADMINISTRATIVAS QUE EJERCE?', 'LAS PERSONAS JURÍDICAS SUJETAS AL RÉGIMEN PRIVADO DESCRITAS EN EL INCISO 8 DEL ARTÍCULO PRIMERO DEL TÍTULO PRELIMINAR DE LA LEY 27444 QUE GESTIONEN SERVICIOS PÚBLICOS O EJERZAN FUNCIONES ADMINISTRATIVAS DEL SECTOR PÚBLICO BAJO CUALQUIER MODALIDAD.', 'ART. 9', '186284'),
    (1069, 'SUB-1069', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA. ¿QUÉ SUCEDE CUANDO EXCEPCIONALMENTE PARA LA ENTIDAD, SEA MATERIALMENTE IMPOSIBLE CUMPLIR CON EL PLAZO SEÑALADO EN EL LITERAL B, DEBIDO A CAUSAS JUSTIFICADAS, RELACIONADAS A LA COMPROBADA Y MANIFIESTA FALTA DE CAPACIDAD LOGÍSTICA U OPERATIVA, O DE RECURSOS HUMANOS DE LA ENTIDAD, O AL SIGNIFICATIVO VOLUMEN DE LA INFORMACIÓN SOLICITADA?', 'POR ÚNICA VEZ LA ENTIDAD DEBE COMUNICAR AL SOLICITANTE LA FECHA EN QUE PROPORCIONARÁ LA INFORMACIÓN SOLICITADA DE FORMA DEBIDAMENTE FUNDAMENTADA, EN UN PLAZO MÁXIMO DE 2 DÍAS HÁBILES DE RECIBIDO EL PEDIDO DE INFORMACIÓN.', 'ART. 11', '186287'),
    (1070, 'SUB-1070', 'SBM2', 'PROMOVER LA TRANSPARENCIA DE LOS ACTOS DEL ESTADO Y REGULAR EL DERECHO FUNDAMENTAL DEL ACCESO A LA INFORMACIÓN CONSAGRADO EN EL NUMERAL 5 DEL ARTÍCULO 2 DE LA CONSTITUCIÓN POLÍTICA DEL PERÚ, CONSTITUYE:', 'LA FINALIDAD DE LA LEY 27806.', 'ART. 1', '186289'),
    (1071, 'SUB-1071', 'SBM2', 'LA PRESENTE LEY TIENE POR FINALIDAD PROMOVER LA TRANSPARENCIA DE LOS ACTOS DEL ESTADO Y REGULAR EL DERECHO FUNDAMENTAL DEL ACCESO A LA INFORMACIÓN CONSAGRADO EN EL:', 'NUMERAL 5 DEL ARTÍCULO 2 DE LA CONSTITUCIÓN POLÍTICA DEL PERÚ.', 'ART. 1', '186290'),
    (1072, 'SUB-1072', 'SBM2', 'PARA EFECTOS DE LA PRESENTE LEY SE ENTIENDE POR ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA A LAS SEÑALADAS EN EL:', 'ARTÍCULO PRIMERO DEL TÍTULO PRELIMINAR DE LA LEY 27444.', 'ART. 2', '186291'),
    (1073, 'SUB-1073', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, ¿QUÉ SUCEDE EN EL SUPUESTO QUE LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA NO ESTÉ OBLIGADA A POSEER LA INFORMACIÓN SOLICITADA Y CONOZCA SU UBICACIÓN O DESTINO?', 'LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA DEBE RE ENCAUSAR LA SOLICITUD HACIA LA ENTIDAD OBLIGADA O HACIA LA QUE LA POSEA, Y PONER EN CONOCIMIENTO DE DICHA CIRCUNSTANCIA AL SOLICITANTE.', 'ART. 11', '186292'),
    (1074, 'SUB-1074', 'SBM2', 'RESPECTO AL PROCEDIMIENTO DE ACCESO A LA INFORMACIÓN PÚBLICA, LA DENEGATORIA AL ACCESO A LA INFORMACIÓN SE SUJETA A LO DISPUESTO EN EL SEGUNDO PÁRRAFO DEL ARTÍCULO:', '13 DE LA PRESENTE LEY.', 'ART. 11', '186293'),
    (1075, 'SUB-1075', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LOS PROYECTOS DE LA LEY DE ENDEUDAMIENTO, EQUILIBRIO FINANCIERO Y PRESUPUESTO Y SU EXPOSICIÓN DE MOTIVOS, DENTRO DE:', 'LOS 2 PRIMEROS DÍAS HÁBILES DE SETIEMBRE.', 'ART. 26', '186295'),
    (1076, 'SUB-1076', 'SBM2', 'RESPECTO A LA DENEGATORIA DE ACCESO A LA INFORMACIÓN PÚBLICA; SI EL REQUERIMIENTO DE INFORMACIÓN NO HUBIERE SIDO SATISFECHO, LA RESPUESTA HUBIERE SIDO AMBIGUA, O NO SE HUBIEREN CUMPLIDO LAS EXIGENCIAS PRECEDENTES, SE CONSIDERARÁ QUE EXISTIÓ:', 'NEGATIVA EN BRINDARLA.', 'ART. 13', '186296'),
    (1077, 'SUB-1077', 'SBM2', 'RESPECTO A LA DENEGATORIA DE ACCESO A LA INFORMACIÓN PÚBLICA; NO SE PODRÁ NEGAR INFORMACIÓN CUANDO SE SOLICITE QUE ESTA SEA ENTREGADA EN UNA DETERMINADA FORMA O MEDIO, SIEMPRE QUE:', 'EL SOLICITANTE ASUMA EL COSTO QUE SUPONGA EL PEDIDO.', 'ART. 13', '186297'),
    (1078, 'SUB-1078', 'SBM2', '"SE APLICA A TODAS LAS INSTITUCIONES INTEGRANTES DEL SISTEMA DE JUSTICIA: PODER JUDICIAL, MINISTERIO PÚBLICO, JUNTA NACIONAL DE JUSTICIA, TRIBUNAL CONSTITUCIONAL Y ACADEMIA DE LA MAGISTRATURA". EL PÁRRAFO ANTERIOR SE REFIERE A:', 'ÁMBITO DE APLICACIÓN DEL RÉGIMEN LEGAL DE TRANSPARENCIA', 'ART. 38', '186298'),
    (1079, 'SUB-1079', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LOS INGRESOS Y GASTOS DEL GOBIERNO CENTRAL E INSTANCIAS DESCENTRALIZADAS COMPRENDIDAS EN LA LEY DE PRESUPUESTO DEL SECTOR PÚBLICO, DE CONFORMIDAD CON LOS CLASIFICADORES DE INGRESOS, GASTOS Y FINANCIAMIENTO VIGENTE, TRIMESTRALMENTE, INCLUYENDO EL PRESUPUESTO ANUAL Y EL DEVENGADO, DE ACUERDO A LOS SIGUIENTES CRITERIOS:', 'IDENTIFICACIÓN INSTITUCIONAL; CLASIFICADOR FUNCIONAL (FUNCIÓN/PROGRAMA); POR GENÉRICA DE GASTO; Y POR FUENTE DE FINANCIAMIENTO.', 'ART. 26', '186299'),
    (1080, 'SUB-1080', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'LOS RESULTADOS DE LA EVALUACIÓN OBTENIDA DE CONFORMIDAD CON LOS INDICADORES APLICADOS, DENTRO DE LOS NOVENTA (90) DÍAS CALENDARIO SIGUIENTES DE CONCLUIDO EL EJERCICIO FISCAL', 'ART. 26', '186301'),
    (1081, 'SUB-1081', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LOS INGRESOS Y GASTOS DEL GOBIERNO CENTRAL E INSTANCIAS DESCENTRALIZADAS COMPRENDIDAS EN LA LEY DE PRESUPUESTO DEL SECTOR PÚBLICO, DE CONFORMIDAD CON LOS CLASIFICADORES DE INGRESOS, GASTOS Y FINANCIAMIENTO VIGENTE, TRIMESTRALMENTE, INCLUYENDO:', 'EL PRESUPUESTO ANUAL Y EL DEVENGADO.', 'ART. 26', '186302'),
    (1082, 'SUB-1082', 'SBM2', 'INDIQUE TODAS LAS INSTITUCIONES QUE CONFORMAN EL SISTEMA DE JUSTICIA:', 'PODER JUDICIAL, MINISTERIO PÚBLICO, JUNTA NACIONAL DE JUSTICIA, TRIBUNAL CONSTITUCIONAL Y ACADEMIA DE LA MAGISTRATURA.', 'ART. 38', '186303'),
    (1083, 'SUB-1083', 'SBM2', 'INCLUIRÁ UN CUADRO DE CONSISTENCIA CON EL MARCO MACROECONÓMICO MULTIANUAL, DESAGREGADO LOS INGRESOS, GASTOS Y RESULTADO ECONÓMICO PARA EL CONJUNTO DE LAS ENTIDADES DENTRO DEL ÁMBITO DE LA LEY ANUAL DE PRESUPUESTO, DEL RESTO DE ENTIDADES QUE CONFORMAN EL SECTOR PÚBLICO CONSOLIDADO:', 'LA EXPOSICIÓN DE MOTIVOS DE LA LEY ANUAL DE PRESUPUESTO.', 'ART. 31', '186304'),
    (1084, 'SUB-1084', 'SBM2', 'TODO PROYECTO DE LEY QUE MODIFIQUE EL GASTO TRIBUTARIO, DEBERÁ ESTAR ACOMPAÑADO DE UNA:', 'ESTIMACIÓN ANUAL DEL IMPACTO QUE DICHA MEDIDA TENDRÍA SOBRE EL PRESUPUESTO PÚBLICO Y SU EFECTO POR REGIONES, SECTORES ECONÓMICOS Y SOCIALES, SEGÚN SU NATURALEZA.', 'ART. 30', '186305'),
    (1085, 'SUB-1085', 'SBM2', 'CONJUNTAMENTE CON LA LEY DE PRESUPUESTO, LA LEY DE EQUILIBRIO FINANCIERO Y LA LEY DE ENDEUDAMIENTO INTERNO Y EXTERNO, EL PODER EJECUTIVO REMITIRÁ AL CONGRESO:', 'UN ESTIMADO DEL EFECTO QUE TENDRÁ EL DESTINO DEL GASTO TRIBUTARIO, POR REGIONES, SECTORES ECONÓMICOS Y SOCIALES, SEGÚN SU NATURALEZA.', 'ART.30', '186306'),
    (1086, 'SUB-1086', 'SBM2', 'EL OSCE PUBLICARÁ TRIMESTRALMENTE:', 'LA INFORMACIÓN DE LAS ADQUISICIONES Y CONTRATACIONES REALIZADAS POR LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA, CUYO VALOR REFERENCIAL HAYA SIDO IGUAL O SUPERIOR A 50 UNIDADES IMPOSITIVAS TRIBUTARIAS.', 'ART. 29', '186307'),
    (1087, 'SUB-1087', 'SBM2', 'EL OSCE PUBLICARÁ, TRIMESTRALMENTE, INFORMACIÓN DE LAS ADQUISICIONES Y CONTRATACIONES REALIZADAS POR LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA, CUYO VALOR REFERENCIAL HAYA SIDO IGUAL O SUPERIOR A:', '50 UNIDADES IMPOSITIVAS TRIBUTARIAS.', 'ART. 29', '186308'),
    (1088, 'SUB-1088', 'SBM2', 'LA ONP, EN CALIDAD DE SECRETARÍA TÉCNICA DEL FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR), PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LOS ESTADOS FINANCIEROS DE CIERRE DEL EJERCICIO FISCAL DE FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR) Y DEL FONDO NACIONAL DE AHORRO PÚBLICO (FONAHPU), ANTES DEL:', '31 DE MARZO DE CADA AÑO.', 'ART. 28', '186309'),
    (1089, 'SUB-1089', 'SBM2', 'LA ONP, EN CALIDAD DE SECRETARÍA TÉCNICA DEL FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR), PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LA INFORMACIÓN REFERENTE A LA SITUACIÓN DE LOS ACTIVOS FINANCIEROS DEL FCR Y DEL FONAHPU, COLOCADOS EN LAS ENTIDADES FINANCIERAS Y NO FINANCIERAS Y EN ORGANISMOS MULTILATERALES DONDE SE ENCUENTREN DEPOSITADOS LOS RECURSOS DE LOS REFERIDOS FONDOS, ASÍ COMO LOS COSTOS DE ADMINISTRACIÓN, LAS TASAS DE INTERÉS, Y LOS INTERESES DEVENGADOS:', 'TRIMESTRALMENTE.', 'ART. 28', '186310'),
    (1090, 'SUB-1090', 'SBM2', '¿QUÉ ENTIDAD PUBLICARÁ, TRIMESTRALMENTE, INFORMACIÓN DE LAS ADQUISICIONES Y CONTRATACIONES REALIZADAS POR LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA, CUYO VALOR REFERENCIAL HAYA SIDO IGUAL O SUPERIOR A 50 UNIDADES IMPOSITIVAS TRIBUTARIAS?', 'OSCE.', 'ART. 29', '186311'),
    (1091, 'SUB-1091', 'SBM2', 'LA ONP, EN CALIDAD DE SECRETARÍA TÉCNICA DEL FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR), PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LO SIGUIENTE: (INDIQUE LA ALTERNATIVA CORRECTA)', 'INFORMACIÓN REFERENTE A LA SITUACIÓN DE LOS ACTIVOS FINANCIEROS DEL FCR Y DEL FONAHPU, COLOCADOS EN LAS ENTIDADES FINANCIERAS Y NO FINANCIERAS Y EN ORGANISMOS MULTILATERALES DONDE SE ENCUENTREN DEPOSITADOS LOS RECURSOS DE LOS REFERIDOS FONDOS, ASÍ COMO LOS COSTOS DE ADMINISTRACIÓN, LAS TASAS DE INTERÉS, Y LOS INTERESES DEVENGADOS, TRIMESTRALMENTE.', 'ART. 28', '186312'),
    (1092, 'SUB-1092', 'SBM2', 'EL FONAFE PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LOS ESTADOS FINANCIEROS AUDITADOS, DENTRO DE LOS:', '120 DÍAS CALENDARIO DE CONCLUIDO EL EJERCICIO FISCAL. TUO Ley N°27806', 'ART. 27', '186313'),
    (1093, 'SUB-1093', 'SBM2', '¿QUÉ ENTIDAD TIENE LA CALIDAD DE SECRETARÍA TÉCNICA DEL FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR)?', 'LA OFICINA DE NORMALIZACIÓN PREVISIONAL (ONP).', 'ART. 28', '186314'),
    (1094, 'SUB-1094', 'SBM2', 'LA ONP, EN CALIDAD DE SECRETARÍA TÉCNICA DEL FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR), PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LO SIGUIENTE:', 'LOS ESTADOS FINANCIEROS DE CIERRE DEL EJERCICIO FISCAL DE FONDO CONSOLIDADO DE RESERVA PREVISIONAL (FCR) Y DEL FONDO NACIONAL DE AHORRO PÚBLICO (FONAHPU), ANTES DEL 31 DE MARZO DE CADA AÑO.', 'ART. 28', '186315'),
    (1095, 'SUB-1095', 'SBM2', 'EL FONAFE PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, EL BALANCE, ASÍ COMO LA CUENTA DE AHORRO, INVERSIÓN Y FINANCIAMIENTO:', 'TRIMESTRALMENTE.', 'ART. 27', '186316'),
    (1096, 'SUB-1096', 'SBM2', 'EL FONAFE PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LOS RESULTADOS DE LA EVALUACIÓN OBTENIDA DE CONFORMIDAD CON LOS INDICADORES APLICADOS, DENTRO DE LOS:', '90 DÍAS CALENDARIO SIGUIENTES DE CONCLUIDO EL EJERCICIO FISCAL.', 'ART. 27', '186317'),
    (1097, 'SUB-1097', 'SBM2', 'EL FONAFE PUBLICARÁ ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, EL PRESUPUESTO EN FORMA CONSOLIDADA, ANTES DEL:', '31 DE DICIEMBRE DEL AÑO PREVIO AL INICIO DEL PERÍODO DE EJECUCIÓN PRESUPUESTAL.', 'ART. 27', '186318'),
    (1098, 'SUB-1098', 'SBM2', 'EL FONAFE PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25, LA SIGUIENTE INFORMACIÓN SOBRE LAS ENTIDADES BAJO SU ÁMBITO:', 'LOS INDICADORES DE GESTIÓN QUE LE SERÁN APLICADOS, CUANDO SE HAYAN CELEBRADO CONVENIOS DE GESTIÓN.', 'ART. 27', '186319'),
    (1099, 'SUB-1099', 'SBM2', '¿QUIÉN ESTARÁ A CARGO DE LA SUPERVISIÓN DEL CUMPLIMIENTO DE LAS OBLIGACIONES DE TRANSPARENCIA CONTENIDAS EN LA PRESENTE LEY?', 'LA AUTORIDAD NACIONAL DE TRANSPARENCIA Y DE ACCESO A LA INFORMACIÓN.', 'ART. 40', '186320'),
    (1100, 'SUB-1100', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'ACCESO AL REGISTRO NACIONAL DE ABOGADOS SANCIONADOS POR MALA PRÁCTICA PROFESIONAL, CREADO POR EL DECRETO LEGISLATIVO 1265 Y SU REGLAMENTO APROBADO POR EL DECRETO SUPREMO 002-2017-JUS.', 'ART. 39', '186321')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

