INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 1101 a 1200
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (1101, 'SUB-1101', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'INFORMACIÓN DETALLADA Y ÚTIL PARA LA GENERACIÓN DE POLÍTICAS PÚBLICAS EN LA MATERIA.', 'ART. 39', '186322'),
    (1102, 'SUB-1102', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'LOS PROCESOS DE SELECCIÓN Y NOMBRAMIENTO, RATIFICACIÓN Y DISCIPLINARIOS DE LOS JUECES Y FISCALES POR LA JUNTA NACIONAL DE JUSTICIA.', 'ART. 39', '186323'),
    (1103, 'SUB-1103', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'LOS INFORMES ELABORADOS POR LAS OFICINAS DE CONTROL DEL PODER JUDICIAL Y DEL MINISTERIO PÚBLICO O LAS QUE HAGAN SUS VECES.', 'ART. 39', '186324'),
    (1104, 'SUB-1104', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'LOS INFORMES ANUALES DE LAS ENTIDADES QUE INTEGRAN EL SISTEMA DE JUSTICIA SOBRE LAS ACTIVIDADES REALIZADAS EN EL MARCO DE SUS COMPETENCIAS.', 'ART. 39', '186325'),
    (1105, 'SUB-1105', 'SBM2', 'LAS ENTIDADES QUE FORMAN PARTE DEL SISTEMA DE JUSTICIA ESTÁN OBLIGADAS A PUBLICAR EN SUS RESPECTIVOS PORTALES DE TRANSPARENCIA, POR LO MENOS, LA SIGUIENTE INFORMACIÓN:', 'LA RELACIÓN DE ENTREVISTAS Y VISITAS QUE TENGAN LOS JUECES Y FISCALES Y, EN GENERAL, DE LOS MIEMBROS DE LA JUNTA NACIONAL DE JUSTICIA, DEL TRIBUNAL CONSTITUCIONAL Y DE LA ACADEMIA DE LA MAGISTRATURA, CON INDICACIÓN DEL ASUNTO QUE LAS HAYA MOTIVADO.', 'ART. 39', '186326'),
    (1106, 'SUB-1106', 'SBM2', '¿QUÉ DOCUMENTO PERMITE CONOCER SI LOS MIEMBROS DEL SISTEMA DE JUSTICIA ESTÁN O NO INCURSOS EN SITUACIONES EN LAS CUALES SUS INTERESES PERSONALES, LABORALES, ECONÓMICOS O FINANCIEROS PUDIERAN ESTAR EN CONFLICTO CON EL CUMPLIMIENTO DE LOS DEBERES Y FUNCIONES DEL CARGO?', 'LA DECLARACIÓN JURADA DE INTERESES.', 'ART. 39', '186327'),
    (1107, 'SUB-1107', 'SBM2', 'CONSTITUYE UNA DE LAS SANCIONES QUE PUEDEN IMPONERSE POR LAS INFRACCIONES A LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA:', 'INHABILITACIÓN.', 'ART. 35', '186330'),
    (1108, 'SUB-1108', 'SBM2', 'CONSTITUYE UNA CLASIFICACIÓN DE LAS INFRACCIONES:', 'INFRACCIÓN LEVE.', 'ART. 36', '186331'),
    (1109, 'SUB-1109', 'SBM2', 'CONSTITUYE UNA CLASIFICACIÓN DE LAS INFRACCIONES:', 'INFRACCIÓN GRAVE.', 'ART. 36', '186332'),
    (1110, 'SUB-1110', 'SBM2', 'CONSTITUYE UNA CLASIFICACIÓN DE LAS INFRACCIONES:', 'INFRACCIÓN MUY GRAVE.', 'ART. 36', '186333'),
    (1111, 'SUB-1111', 'SBM2', 'LAS INFRACCIONES SE CLASIFICAN EN LEVES, GRAVES Y MUY GRAVES, LAS CUALES SON TIPIFICADAS VÍA REGLAMENTARIA, DE ACUERDO A LO ESTABLECIDO EN EL NUMERAL 4 DEL ARTÍCULO 230 DE LA LEY 27444, LEY DEL PROCEDIMIENTO ADMINISTRATIVO GENERAL, MEDIANTE DECRETO SUPREMO, REFRENDADO POR:', 'EL MINISTERIO DE JUSTICIA Y DERECHOS HUMANOS.', 'ART. 36', '186334'),
    (1112, 'SUB-1112', 'SBM2', 'CONSTITUYE UNA DE LAS SANCIONES QUE PUEDEN IMPONERSE POR LAS INFRACCIONES A LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA:', 'DESTITUCIÓN.', 'ART. 35', '186335'),
    (1113, 'SUB-1113', 'SBM2', 'CONSTITUYE UNA DE LAS SANCIONES QUE PUEDEN IMPONERSE POR LAS INFRACCIONES A LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA:', 'MULTA NO MAYOR DE CINCO UNIDADES IMPOSITIVAS TRIBUTARIAS.', 'ART. 35', '186336'),
    (1114, 'SUB-1114', 'SBM2', 'CONSTITUYE UNA DE LAS SANCIONES QUE PUEDEN IMPONERSE POR LAS INFRACCIONES A LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA:', 'AMONESTACIÓN ESCRITA.', 'ART. 35', '186337'),
    (1115, 'SUB-1115', 'SBM2', 'CONSTITUYE UNA DE LAS SANCIONES QUE PUEDEN IMPONERSE POR LAS INFRACCIONES A LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA:', 'SUSPENSIÓN SIN GOCE DE HABER ENTRE DIEZ Y CIENTO OCHENTA DÍAS.', 'ART. 35', '186338'),
    (1116, 'SUB-1116', 'SBM2', 'ES APLICABLE A LAS ACCIONES U OMISIONES QUE INFRINJAN EL RÉGIMEN JURÍDICO DE LA TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA, TIPIFICADAS EN EL TÍTULO QUINTO, DE CONFORMIDAD CON EL ARTÍCULO 4 DE LA PRESENTE LEY:', 'EL RÉGIMEN SANCIONADOR.', 'ART. 34', '186339'),
    (1117, 'SUB-1117', 'SBM2', 'LA PRESIDENCIA DEL CONSEJO DE MINISTROS, CON UNA ANTICIPACIÓN NO MENOR DE 3 MESES A LA FECHA ESTABLECIDA PARA LAS ELECCIONES GENERALES, PUBLICARÁ UNA RESEÑA DE LO REALIZADO DURANTE SU ADMINISTRACIÓN Y EXPONDRÁ SUS PROYECCIONES SOBRE LA SITUACIÓN ECONÓMICA, FINANCIERA Y SOCIAL DE LOS PRÓXIMOS:', '5 AÑOS.', 'ART. 32', '186340'),
    (1118, 'SUB-1118', 'SBM2', 'LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA CUYO PRESUPUESTO NO FORME PARTE DEL PRESUPUESTO GENERAL DE LA REPÚBLICA, DEBEN APROBAR ÉSTE A MÁS TARDAR AL:', '15 DE DICIEMBRE DEL AÑO PREVIO A SU ENTRADA EN VIGENCIA, POR EL ÓRGANO CORRESPONDIENTE ESTABLECIDO EN LAS NORMAS VIGENTES.', 'ART. 33', '186341'),
    (1119, 'SUB-1119', 'SBM2', 'PUBLICARÁ UNA RESEÑA DE LO REALIZADO DURANTE SU ADMINISTRACIÓN Y EXPONDRÁ SUS PROYECCIONES SOBRE LA SITUACIÓN ECONÓMICA, FINANCIERA Y SOCIAL DE LOS PRÓXIMOS 5 AÑOS.', 'LA PRESIDENCIA DEL CONSEJO DE MINISTROS.', 'ART. 32', '186342'),
    (1120, 'SUB-1120', 'SBM2', 'LA PRESIDENCIA DEL CONSEJO DE MINISTROS, PUBLICARÁ UNA RESEÑA DE LO REALIZADO DURANTE SU ADMINISTRACIÓN Y EXPONDRÁ SUS PROYECCIONES SOBRE LA SITUACIÓN ECONÓMICA, FINANCIERA Y SOCIAL DE LOS PRÓXIMOS 5 AÑOS, CON UNA ANTICIPACIÓN NO MENOR DE:', '3 MESES A LA FECHA ESTABLECIDA PARA LAS ELECCIONES GENERALES.', 'ART. 32', '186343'),
    (1121, 'SUB-1121', 'SBM2', 'INCLUIRÁ LA SUSTENTACIÓN DE SU COMPATIBILIDAD CON EL DÉFICIT Y EL CONSIGUIENTE AUMENTO DE DEUDA PREVISTO EN EL MARCO MACROECONÓMICO MULTIANUAL.', 'LA EXPOSICIÓN DE MOTIVOS DE LA LEY ANUAL DE ENDEUDAMIENTO.', 'ART. 31', '186344'),
    (1122, 'SUB-1122', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'EL BALANCE DEL FONDO DE ESTABILIZACIÓN FISCAL (FEF) DENTRO DE LOS 30 DÍAS CALENDARIO DE CONCLUIDO EL EJERCICIO FISCAL.', 'ART. 26', '186345'),
    (1123, 'SUB-1123', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'INFORMACIÓN SOBRE LOS PROYECTOS DE INVERSIÓN PÚBLICA CUYOS ESTUDIOS O EJECUCIÓN HUBIESEN DEMANDADO RECURSOS IGUALES O SUPERIORES A MIL DOSCIENTAS (1 200) UNIDADES IMPOSITIVAS TRIBUTARIAS, TRIMESTRALMENTE, INCLUYENDO: EL PRESUPUESTO TOTAL DEL PROYECTO, EL PRESUPUESTO EJECUTADO ACUMULADO Y PRESUPUESTO EJECUTADO ANUAL.', 'ART. 26', '186346'),
    (1124, 'SUB-1124', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'EL CRONOGRAMA DE DESEMBOLSOS Y AMORTIZACIONES REALIZADAS, POR CADA FUENTE DE FINANCIAMIENTO, TRIMESTRALMENTE, INCLUYENDO: OPERACIONES OFICIALES DE CRÉDITO, OTROS DEPÓSITOS Y SALDOS DE BALANCE.', 'ART. 26', '186347'),
    (1125, 'SUB-1125', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'INFORMACIÓN DETALLADA SOBRE EL SALDO Y PERFIL DE LA DEUDA PÚBLICA EXTERNA E INTERNA CONCERTADA O GARANTIZADA POR EL SECTOR PÚBLICO CONSOLIDADO, TRIMESTRALMENTE, INCLUYENDO: EL TIPO DE ACREEDOR, EL MONTO, EL PLAZO, LA TASA DE AMORTIZACIÓN PACTADA, EL CAPITAL Y LOS INTERESES PAGADOS Y POR DEVENGARSE.', 'ART. 26', '186348'),
    (1126, 'SUB-1126', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'LOS PROYECTOS DE LA LEY DE ENDEUDAMIENTO, EQUILIBRIO FINANCIERO Y PRESUPUESTO Y SU EXPOSICIÓN DE MOTIVOS, DENTRO DE LOS 2 PRIMEROS DÍAS HÁBILES DE SETIEMBRE, INCLUYENDO: LOS CUADROS GENERALES SOBRE USO Y FUENTES Y DISTRIBUCIÓN FUNCIONAL POR GENÉRICA DEL GASTO E INSTITUCIONAL, A NIVEL DE PLIEGO.', 'ART. 26', '186349'),
    (1127, 'SUB-1127', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'LOS INGRESOS Y GASTOS DEL GOBIERNO CENTRAL E INSTANCIAS DESCENTRALIZADAS COMPRENDIDAS EN LA LEY DE PRESUPUESTO DEL SECTOR PÚBLICO, DE CONFORMIDAD CON LOS CLASIFICADORES DE INGRESOS, GASTOS Y FINANCIAMIENTO VIGENTE, TRIMESTRALMENTE, INCLUYENDO: EL PRESUPUESTO ANUAL Y EL DEVENGADO, DE ACUERDO A LOS SIGUIENTES CRITERIOS (I) IDENTIFICACIÓN INSTITUCIONAL; (II) CLASIFICADOR FUNCIONAL (FUNCIÓN/PROGRAMA); (III) POR GENÉRICA DE GASTO; Y (IV) POR FUENTE DE FINANCIAMIENTO.', 'ART. 26', '186350'),
    (1128, 'SUB-1128', 'SBM2', 'LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA ESTABLECERÁN PROGRESIVAMENTE, DE ACUERDO A SU PRESUPUESTO, LA DIFUSIÓN A TRAVÉS DE INTERNET DE LA SIGUIENTE INFORMACIÓN:', 'DATOS GENERALES DE LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA.', 'ART. 5', '186351'),
    (1129, 'SUB-1129', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE INFORMACIÓN.- LA INFORMACIÓN QUE POR RAZONES DE SEGURIDAD NACIONAL EN EL ÁMBITO DEL ORDEN INTERNO, CUYA REVELACIÓN ORIGINARÍA UN RIESGO A LA INTEGRIDAD TERRITORIAL Y/O LA SUBSISTENCIA DEL SISTEMA DEMOCRÁTICO. ES CONSIDERADA INFORMACIÓN CLASIFICADA COMO:', 'RESERVADA.', 'ART. 16', '186352'),
    (1130, 'SUB-1130', 'SBM2', 'EL FUNCIONARIO PÚBLICO RESPONSABLE DE DAR INFORMACIÓN, QUE DE MODO ARBITRARIO OBSTRUYA EL ACCESO DEL SOLICITANTE A LA INFORMACIÓN REQUERIDA, SERÁ SANCIONADO POR:', 'LA COMISIÓN DE UNA FALTA GRAVE.', 'ART. 4', '186353'),
    (1131, 'SUB-1131', 'SBM2', 'REGULACIÓN DE LAS EXCEPCIONES.- EL EJERCICIO DE ESTAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA SE ENMARCA DENTRO DE LAS LIMITACIONES QUE SEÑALA:', 'LA CONSTITUCIÓN POLÍTICA DEL PERÚ.', 'ART. 18', '186354'),
    (1132, 'SUB-1132', 'SBM2', 'TODAS LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA QUEDAN OBLIGADAS A CUMPLIR LO ESTIPULADO EN LA PRESENTE NORMA; ESTE ENUNCIADO SE ENCUENTRA CONSIDERADO EN:', 'RESPONSABILIDADES Y SANCIONES.', 'ART. 4', '186355'),
    (1133, 'SUB-1133', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUE CLASIFICACIÓN CORRESPONDE A LA INFORMACIÓN QUE CONTENGA CONSEJOS PRODUCIDOS COMO PARTE DEL PROCESO DELIBERATIVO Y CONSULTIVO PREVIO A LA TOMA DE UNA DECISIÓN DE GOBIERNO, SALVO QUE DICHA INFORMACIÓN SEA PÚBLICA:', 'INFORMACIÓN CONFIDENCIAL.', 'ART. 17', '186356'),
    (1134, 'SUB-1134', 'SBM2', 'TASA APLICABLE.- EL SOLICITANTE QUE REQUIERA LA INFORMACIÓN DEBERÁ ABONAR SOLAMENTE EL IMPORTE CORRESPONDIENTE A LOS COSTOS DE REPRODUCCIÓN DE LA INFORMACIÓN:', 'REQUERIDA.', 'ART. 20', '186357'),
    (1135, 'SUB-1135', 'SBM2', 'EL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA NO PODRÁ SER EJERCIDO RESPECTO DE LA INFORMACIÓN CLASIFICADA COMO RESERVADA. EN CONSECUENCIA LA EXCEPCIÓN COMPRENDE EL SIGUIENTE SUPUESTO:', 'EL ARMAMENTO Y MATERIAL LOGÍSTICO COMPROMETIDO EN OPERACIONES ESPECIALES.', 'ART. 16', '186358'),
    (1136, 'SUB-1136', 'SBM2', 'BAJO RESPONSABILIDAD DE SU MÁXIMO REPRESENTANTE, LAS ENTIDADES OBLIGADAS A BRINDAR INFORMACIÓN IDENTIFICARÁN AL FUNCIONARIO RESPONSABLE DE BRINDAR LA INFORMACIÓN SOLICITADA EN VIRTUD DE LA PRESENTE LEY. EN CASO DE QUE ÉSTE NO HUBIERA SIDO DESIGNADO LAS RESPONSABILIDADES ADMINISTRATIVAS Y PENALES RECAERÁN EN:', 'EL SECRETARIO GENERAL DE LA INSTITUCIÓN O QUIEN HAGA SUS VECES.', 'ART. 8', '186359'),
    (1137, 'SUB-1137', 'SBM2', 'EL DOCUMENTO QUE FUNDAMENTA QUE LA INFORMACIÓN DEBE CONTINUAR COMO CLASIFICADA SECRETA, POR CONSIDERAR QUE SU DIVULGACIÓN PONE EN RIESGO LA INTEGRIDAD TERRITORIAL Y/O SUBSISTENCIA DEL SISTEMA DEMOCRÁTICO, SE PONE EN CONOCIMIENTO DEL:', 'CONSEJO DE MINISTROS.', 'ART. 15', '186360'),
    (1138, 'SUB-1138', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA.- LA INFORMACIÓN QUE TIENE POR FINALIDAD PREVENIR Y REPRIMIR LA CRIMINALIDAD EN EL PAÍS Y CUYA REVELACIÓN PUEDE ENTORPECERLA, COMPRENDE EL MOVIMIENTO DEL PERSONAL QUE PUDIERA PONER EN RIESGO LA VIDA E INTEGRIDAD DE LAS PERSONAS INVOLUCRADAS O AFECTAR LA SEGURIDAD CIUDADANA. ES CONSIDERADA INFORMACIÓN CLASIFICADA COMO:', 'RESERVADA.', 'ART. 16 TUO Ley N°27806', '186361'),
    (1139, 'SUB-1139', 'SBM2', 'EL ESTADO ADOPTA LAS MEDIDAS BÁSICAS QUE GARANTICEN Y PROMUEVAN LA TRANSPARENCIA EN LA ACTUACIÓN DE LAS:', 'ENTIDADES DE LA ADMINISTRACIÓN PUBLICA.', 'ART. 3', '186362'),
    (1140, 'SUB-1140', 'SBM2', '¿TRANSCURRIDO QUÉ PLAZO, EL ARCHIVO NACIONAL PODRÁ DESTRUIR INFORMACIÓN QUE NO TENGA UTILIDAD PÚBLICA?', 'RAZONABLE', 'ART. 21', '186363'),
    (1141, 'SUB-1141', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUÉ CLASIFICACIÓN CORRESPONDE A LA INFORMACIÓN QUE AL SER DIVULGADA OFICIALMENTE POR EL MINISTERIO DE RELACIONES EXTERIORES PUDIERA AFECTAR NEGATIVAMENTE LAS RELACIONES DIPLOMÁTICAS CON OTROS PAÍSES:', 'RESERVADA.', 'ART. 16', '186364'),
    (1142, 'SUB-1142', 'SBM2', '¿A QUÉ PRINCIPIO CORRESPONDE, CUANDO LOS FUNCIONARIOS RESPONSABLES DE BRINDAR INFORMACIÓN EN EL ÁREA DE SU COMPETENCIA DEBERÁN PREVER UNA ADECUADA INFRAESTRUCTURA, ASÍ COMO LA ORGANIZACIÓN, SISTEMATIZACIÓN Y PUBLICACIÓN DE LA INFORMACIÓN?', 'PUBLICIDAD.', 'ART. 3', '186365'),
    (1143, 'SUB-1143', 'SBM2', 'CON POSTERIORIDAD A QUE PLAZO, CUALQUIER PERSONA PUEDE SOLICITAR EL ACCESO A LA INFORMACIÓN CLASIFICADA COMO SECRETA, LA CUAL SERÁ ENTREGADA POR EL TITULAR DEL SECTOR O PLIEGO RESPECTIVO:', 'CINCO AÑOS DE CLASIFICACIÓN.', 'ART. 15', '186366'),
    (1144, 'SUB-1144', 'SBM2', 'LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA PERMITIRÁN A LOS SOLICITANTES, EL ACCESO DIRECTO Y DE MANERA INMEDIATA A LA INFORMACIÓN PÚBLICA DURANTE:', 'LAS HORAS DE ATENCIÓN AL PÚBLICO.', 'ART. 12', '186367'),
    (1145, 'SUB-1145', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUE INFORMACIÓN SE ENCUENTRA COMO CLASIFICADA EN EL ÁMBITO DE INTELIGENCIA TANTO EN EL FRENTE EXTERNO COMO INTERNO:', 'INFORMACIÓN DEL PERSONAL CIVIL O MILITAR QUE DESARROLLA ACTIVIDADES DE SEGURIDAD NACIONAL.', 'ART. 15', '186368'),
    (1146, 'SUB-1146', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUÉ CLASIFICACIÓN TIENE LA INFORMACIÓN VINCULADA A INVESTIGACIONES EN TRÁMITE REFERIDAS AL EJERCICIO DE LA POTESTAD SANCIONADORA DE LA ADMINISTRACIÓN PÚBLICA:', 'CONFIDENCIAL.', 'ART. 17', '186369'),
    (1147, 'SUB-1147', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE INFORMACIÓN CONFIDENCIAL.- EL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA NO PODRÁ SER EJERCIDO RESPECTO A INFORMACIÓN PROTEGIDA REFERIDA A:', 'SECRETO TECNOLÓGICO.', 'ART. 17', '186370'),
    (1148, 'SUB-1148', 'SBM2', 'EL ESTADO TIENE LA OBLIGACIÓN DE ENTREGAR LA INFORMACIÓN QUE DEMANDEN LAS PERSONAS EN APLICACIÓN DEL PRINCIPIO DE:', 'PUBLICIDAD.', 'ART. 3', '186371'),
    (1149, 'SUB-1149', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA.- LA INFORMACIÓN SOBRE LAS ACTIVIDADES Y PLANES ESTRATÉGICOS DE INTELIGENCIA Y CONTRAINTELIGENCIA Y DE LOS ORGANISMOS CONFORMANTES DEL SISTEMA DE INTELIGENCIA NACIONAL; A QUE CLASE DE INFORMACIÓN CORRESPONDE:', 'SECRETA.', 'ART. 15', '186372'),
    (1150, 'SUB-1150', 'SBM2', 'PARA LOS EFECTOS DE LA LEY, TAMBIÉN SE CONSIDERA INFORMACIÓN PÚBLICA CUALQUIER TIPO DE DOCUMENTACIÓN FINANCIADA POR EL PRESUPUESTO PÚBLICO QUE SIRVA DE BASE A:', 'UNA DECISIÓN DE NATURALEZA ADMINISTRATIVA.', 'ART. 10', '186373'),
    (1151, 'SUB-1151', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA RESERVADA.- CONSTITUYE INFORMACIÓN CLASIFICADA COMO RESERVADA, SOBRE LA CUÁL NO SE PODRÁ EJERCER EL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA:', 'LOS PLANES DE SEGURIDAD Y DEFENSA DE INSTALACIONES POLICIALES.', 'ART. 16', '186374'),
    (1152, 'SUB-1152', 'SBM2', 'EL MINISTERIO DE ECONOMÍA Y FINANZAS PUBLICARÁ, ADICIONALMENTE A LO ESTABLECIDO EN EL ARTÍCULO 25 DE LA PRESENTE NORMA, LA SIGUIENTE INFORMACIÓN:', 'EL BALANCE DEL SECTOR PÚBLICO CONSOLIDADO, DENTRO DE LOS 90 DÍAS CALENDARIO DE CONCLUIDO EL EJERCICIO FISCAL, CONJUNTAMENTE CON LOS BALANCES DE LOS DOS EJERCICIOS ANTERIORES.', 'ART. 26', '186375'),
    (1153, 'SUB-1153', 'SBM2', '¿QUÉ INFORMACIÓN SE ENCUENTRA COMO CLASIFICADA EN EL ÁMBITO DE INTELIGENCIA, TANTO EN EL FRENTE EXTERNO COMO INTERNO?', 'LA RELACIONADA CON EL ALISTAMIENTO DEL PERSONAL Y MATERIAL.', 'ART. 15', '186377'),
    (1154, 'SUB-1154', 'SBM2', 'INFORMACIÓN QUE DEBEN PUBLICAR TODAS LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA.- LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA ESTÁN EN LA OBLIGACIÓN DE REMITIR LA INFORMACIÓN INDICADA EN EL ARTÍCULO 25 DE LA PRESENTE NORMA A:', 'MINISTERIO DE ECONOMÍA Y FINANZAS, PARA QUE ÉSTE LA INCLUYA EN SU PORTAL DE INTERNET.', 'ART. 25', '186378'),
    (1155, 'SUB-1155', 'SBM2', 'INFORMACIÓN DE ACCESO PÚBLICO.- PARA LOS EFECTOS DE LA LEY, ES CONSIDERADA INFORMACIÓN PÚBLICA:', 'LAS ACTAS DE REUNIONES OFICIALES.', 'ART. 10', '186380'),
    (1156, 'SUB-1156', 'SBM2', 'LA ENTIDAD PÚBLICA DEBERÁ IDENTIFICAR AL FUNCIONARIO RESPONSABLE DE LA ELABORACIÓN DE LOS:', 'PORTALES DE INTERNET.', 'ART. 5', '186381'),
    (1157, 'SUB-1157', 'SBM2', 'LAS EXCEPCIONES AL EJERCICIO DEL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA, COMPRENDE ÚNICAMENTE DOS SUPUESTOS, UNO DE ELLOS ES:', 'INFORMACIÓN CLASIFICADA EN EL ÁMBITO MILITAR, TANTO EN EL FRENTE INTERNO COMO EXTERNO.', 'ART. 15', '186382'),
    (1158, 'SUB-1158', 'SBM2', 'LA INFORMACIÓN QUE TIENE POR FINALIDAD PREVENIR Y REPRIMIR LA CRIMINALIDAD EN EL PAÍS Y CUYA REVELACIÓN PUEDE ENTORPECERLA, DENTRO DEL CUÁL SE ENCUENTRAN LOS PLANES DE OPERACIONES POLICIALES Y DE INTELIGENCIA, ES CONSIDERADA:', 'INFORMACIÓN RESERVADA.', 'ART. 16', '186383'),
    (1159, 'SUB-1159', 'SBM2', 'EN CASO DE QUE UN DOCUMENTO CONTENGA, EN FORMA PARCIAL, INFORMACIÓN QUE; CONFORME A LOS ARTÍCULOS 15 (SECRETO), 16 (RESERVADO) Y 17 (CONFIDENCIAL) DE ESTA LEY, NO SEA DE ACCESO PÚBLICO, LA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA DEBERÁ:', 'PERMITIR EL ACCESO A LA INFORMACIÓN DISPONIBLE DEL DOCUMENTO.', 'ART. 19', '186384'),
    (1160, 'SUB-1160', 'SBM2', 'LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA TIENEN LA OBLIGACIÓN DE PROVEER LA INFORMACIÓN REQUERIDA SI SE REFIERE A LA CONTENIDA EN:', 'SOPORTE MAGNÉTICO O DIGITAL. TUO Ley N°27806', 'ART. 10', '186385'),
    (1161, 'SUB-1161', 'SBM2', 'TODA PERSONA TIENE DERECHO A SOLICITAR Y RECIBIR INFORMACIÓN DE CUALQUIER ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA. EN NINGÚN CASO SE EXIGE EXPRESIÓN DE CAUSA PARA:', 'EL EJERCICIO DE ESTE DERECHO.', 'ART. 7', '186386'),
    (1162, 'SUB-1162', 'SBM2', '¿A QUÉ PRINCIPIO ESTÁN SOMETIDAS TODAS LAS ACTIVIDADES Y DISPOSICIONES DE LAS ENTIDADES COMPRENDIDAS EN LA PRESENTE LEY?', 'PUBLICIDAD.', 'ART. 3', '186387'),
    (1163, 'SUB-1163', 'SBM2', 'A PARTIR DE QUE FECHA, LAS ENTIDADES DEL GOBIERNO CENTRAL, ORGANISMOS AUTÓNOMOS Y DESCENTRALIZADOS DEBERÁN CONTAR CON PORTALES EN INTERNET:', 'A PARTIR DEL 1 DE JULIO DE 2003.', 'ART. 6', '186388'),
    (1164, 'SUB-1164', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO DE INFORMACIÓN.- LAS INFORMACIONES QUE IMPIDAN EL CURSO DE LAS INVESTIGACIONES EN SU ETAPA POLICIAL DENTRO DE LOS LÍMITES DE LA LEY, INCLUYENDO LOS SISTEMAS DE RECOMPENSA, COLABORACIÓN EFICAZ Y PROTECCIÓN DE TESTIGOS. ES CONSIDERADA INFORMACIÓN CLASIFICADA COMO:', 'INFORMACIÓN RESERVADA.', 'ART. 16', '186389'),
    (1165, 'SUB-1165', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUÉ CLASIFICACIÓN CORRESPONDE A LA INFORMACIÓN REFERIDA A LA SALUD PERSONAL:', 'INFORMACIÓN CONFIDENCIAL.', 'ART. 17', '186390'),
    (1166, 'SUB-1166', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- A QUIÉN SE DEBE FUNDAMENTAR MEDIANTE DOCUMENTO, QUE LA INFORMACIÓN CONTINÚA COMO CLASIFICADA:', 'CONSEJO DE MINISTROS.', 'ART. 15', '186392'),
    (1167, 'SUB-1167', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO.- QUÉ CLASIFICACIÓN CORRESPONDE A LA INFORMACIÓN QUE CONTIENE LOS PLANES DE OPERACIONES POLICIALES Y DE INTELIGENCIA, ASÍ COMO AQUELLOS DESTINADOS A COMBATIR EL TERRORISMO, TRÁFICO ILÍCITO DE DROGAS Y ORGANIZACIONES CRIMINALES:', 'RESERVADA.', 'ART. 16', '186393'),
    (1168, 'SUB-1168', 'SBM2', 'SALVO LAS EXCEPCIONES EXPRESAMENTE PREVISTAS EN LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA, TODA INFORMACIÓN QUE POSEA EL ESTADO SE PRESUME:', 'PÚBLICA.', 'ART. 3', '186394'),
    (1169, 'SUB-1169', 'SBM2', 'EL DERECHO DE ACCESO A LA INFORMACIÓN PÚBLICA NO PODRÁ SER EJERCIDO RESPECTO A LA INFORMACIÓN EXPRESAMENTE CLASIFICADA COMO SECRETA, QUE SE SUSTENTE EN RAZONES DE SEGURIDAD NACIONAL, QUE ADEMÁS TENGA COMO BASE FUNDAMENTAL GARANTIZAR:', 'LA SEGURIDAD DE LAS PERSONAS.', 'ART. 15', '186395'),
    (1170, 'SUB-1170', 'SBM2', '¿QUIÉN ADOPTA LAS MEDIDAS BÁSICAS QUE GARANTICEN Y PROMUEVAN LA TRANSPARENCIA EN LA ACTUACIÓN DE LAS ENTIDADES DE LA ADMINISTRACIÓN PÚBLICA?', 'EL ESTADO.', 'ART. 3', '186396'),
    (1171, 'SUB-1171', 'SBM2', 'EXCEPCIONES AL EJERCICIO DEL DERECHO: A QUÉ CLASIFICACIÓN CORRESPONDE LA INFORMACIÓN PROTEGIDA POR EL SECRETO BANCARIO, TRIBUTARIO, COMERCIAL, INDUSTRIAL, TECNOLÓGICO Y BURSÁTIL QUE ESTÁN REGULADOS POR LA CONSTITUCIÓN Y LAS LEYES:', 'INFORMACIÓN CONFIDENCIAL.', 'ART. 17', '186397'),
    (1172, 'SUB-1172', 'SBM2', 'LOS CASOS ESTABLECIDOS EN LOS ARTÍCULOS 15, 16 Y 17 SON LOS ÚNICOS EN LOS QUE SE PUEDE LIMITAR EL DERECHO AL ACCESO A LA INFORMACIÓN PÚBLICA, POR LO QUE DEBEN SER INTERPRETADOS DE MANERA RESTRICTIVA POR TRATARSE DE UNA LIMITACIÓN A:', 'UN DERECHO FUNDAMENTAL.', 'ART. 18', '186399'),
    (1173, 'SUB-1173', 'SBM2', 'TODA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA PUBLICARÁ TRIMESTRALMENTE LA INFORMACIÓN CONTENIDA EN EL REGISTRO DE PROCESOS DE SELECCIÓN DE CONTRATACIONES Y ADQUISICIONES, ESPECIFICANDO:', 'LOS VALORES REFERENCIALES, NOMBRES DE CONTRATISTAS, MONTOS DE LOS CONTRATOS, PENALIDADES Y SANCIONES Y COSTO FINAL, DE SER EL CASO.', 'ART. 25', '186400'),
    (1174, 'SUB-1174', 'SBM2', 'TODA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA PUBLICARÁ TRIMESTRALMENTE LA INFORMACIÓN DE SU PERSONAL, ESPECIFICANDO:', 'PERSONAL ACTIVO Y, DE SER EL CASO, PASIVO, NÚMERO DE FUNCIONARIOS, DIRECTIVOS, PROFESIONALES, TÉCNICOS, AUXILIARES, SEAN ÉSTOS NOMBRADOS O CONTRATADOS POR UN PERÍODO MAYOR A 3 MESES EN EL PLAZO DE UN AÑO, SIN IMPORTAR EL RÉGIMEN LABORAL AL QUE SE ENCUENTREN SUJETOS, O LA DENOMINACIÓN DEL PRESUPUESTO O CARGO QUE DESEMPEÑEN; RANGO SALARIAL POR CATEGORÍA Y EL TOTAL DEL GASTO DE REMUNERACIONES, BONIFICACIONES, Y CUALQUIER OTRO CONCEPTO DE ÍNDOLE REMUNERATIVO, SEA PENSIONABLE O NO.', 'ART. 25', '186401'),
    (1175, 'SUB-1175', 'SBM2', 'TODA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA PUBLICARÁ TRIMESTRALMENTE LOS PROYECTOS DE INVERSIÓN PÚBLICA EN EJECUCIÓN, ESPECIFICANDO:', 'EL PRESUPUESTO TOTAL DE PROYECTO, EL PRESUPUESTO DEL PERÍODO CORRESPONDIENTE Y SU NIVEL DE EJECUCIÓN Y EL PRESUPUESTO ACUMULADO.', 'ART. 25', '186402'),
    (1176, 'SUB-1176', 'SBM2', 'TODA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA PUBLICARÁ TRIMESTRALMENTE SU PRESUPUESTO, ESPECIFICANDO:', 'LOS INGRESOS, GASTOS, FINANCIAMIENTO, Y RESULTADOS OPERATIVOS DE CONFORMIDAD CON LOS CLASIFICADORES PRESUPUESTALES VIGENTES.', 'ART. 25', '186403'),
    (1177, 'SUB-1177', 'SBM2', '¿CADA CUÁNTO TIEMPO UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA DEBE PUBLICAR LOS PROGRESOS REALIZADOS EN LOS INDICADORES DE DESEMPEÑO ESTABLECIDOS EN LOS PLANES ESTRATÉGICOS INSTITUCIONALES O EN LOS INDICADORES QUE LES SERÁN APLICADOS, EN EL CASO DE ENTIDADES QUE HAYAN SUSCRITO CONVENIOS DE GESTIÓN?', 'TRIMESTRALMENTE.', 'ART. 25', '186404'),
    (1178, 'SUB-1178', 'SBM2', '¿CADA CUÁNTO TIEMPO UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA DEBE PUBLICAR LA INFORMACIÓN CONTENIDA EN EL REGISTRO DE PROCESOS DE SELECCIÓN DE CONTRATACIONES Y ADQUISICIONES, ESPECIFICANDO: LOS VALORES REFERENCIALES, NOMBRES DE CONTRATISTAS, MONTOS DE LOS CONTRATOS, PENALIDADES Y SANCIONES Y COSTO FINAL, DE SER EL CASO?', 'TRIMESTRALMENTE.', 'ART. 25', '186405'),
    (1179, 'SUB-1179', 'SBM2', '¿CADA CUÁNTO TIEMPO, UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA, DEBE PUBLICAR LA INFORMACIÓN DE SU PERSONAL ESPECIFICANDO: PERSONAL ACTIVO, Y DE SER EL CASO, PASIVO; NÚMERO DE FUNCIONARIOS, DIRECTIVOS, PROFESIONALES, TÉCNICOS, AUXILIARES, SEAN ÉSTOS NOMBRADOS O CONTRATADOS POR UN PERÍODO MAYOR A 3 MESES EN EL PLAZO DE UN AÑO, SIN IMPORTAR EL RÉGIMEN LABORAL AL QUE SE ENCUENTREN SUJETOS, O LA DENOMINACIÓN DEL PRESUPUESTO O CARGO QUE DESEMPEÑEN; RANGO SALARIAL POR CATEGORÍA Y EL TOTAL DEL GASTO DE REMUNERACIONES, BONIFICACIONES, Y CUALQUIER OTRO CONCEPTO DE ÍNDOLE REMUNERATIVO, SEA PENSIONABLE O NO?', 'TRIMESTRALMENTE.', 'ART. 25', '186406'),
    (1180, 'SUB-1180', 'SBM2', '¿CADA CUÁNTO TIEMPO UNA ENTIDAD DE LA ADMINISTRACIÓN PÚBLICA DEBE PUBLICAR LOS PROYECTOS DE INVERSIÓN PÚBLICA EN EJECUCIÓN, ESPECIFICANDO: EL PRESUPUESTO TOTAL DE PROYECTO, EL PRESUPUESTO DEL PERÍODO CORRESPONDIENTE Y SU NIVEL DE EJECUCIÓN Y EL PRESUPUESTO ACUMULADO?', 'TRIMESTRALMENTE.', 'ART. 25', '186407'),
    (1181, 'SUB-1181', 'SBM2', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN CAPITÁN DE ARMAS PARA SER CANDIDATO AL ASCENSO?', '5 AÑOS', 'ART. 8', '186693'),
    (1182, 'SUB-1182', 'SBM2', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN TENIENTE DE ARMAS PARA SER CANDIDATO AL ASCENSO?', '5 AÑOS', 'ART. 8', '186694'),
    (1183, 'SUB-1183', 'SBM2', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN ALFÉREZ PARA SER CANDIDATO AL ASCENSO?', '5 AÑOS', 'ART. 8', '186695'),
    (1184, 'SUB-1184', 'SBM2', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN CORONEL DE ARMAS PARA SER CANDIDATO AL ASCENSO?', '4 AÑOS', 'ART. 8', '186696'),
    (1185, 'SUB-1185', 'SBM2', '¿CUÁL ES EL TIEMPO MÍNIMO DE SERVICIO REALES Y EFECTIVOS EN EL GRADO QUE DEBE TENER UN COMANDANTE DE ARMAS PARA SER CANDIDATO AL ASCENSO?', '5 AÑOS', 'ART. 8', '186697'),
    (1186, 'SUB-1186', 'SBM2', 'CONSTITUYE UN PRINCIPIO RECTOR DE LOS PROCESOS DE ASCENSOS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'PRINCIPIO DE IGUALDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO Ley N° 31873 - Ley que Regula Los Procesos de Ascenso PNP', '186699'),
    (1187, 'SUB-1187', 'SBM2', 'CONSTITUYE UN PRINCIPIO RECTOR DE LOS PROCESOS DE ASCENSOS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'PRINCIPIO DE IMPARCIALIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186700'),
    (1188, 'SUB-1188', 'SBM2', 'CONSTITUYE UN PRINCIPIO RECTOR DE LOS PROCESOS DE ASCENSOS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'PRINCIPIO DE OBJETIVIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186702'),
    (1189, 'SUB-1189', 'SBM2', 'CONSTITUYE UN PRINCIPIO RECTOR DE LOS PROCESOS DE ASCENSOS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'PRINCIPIO DE TRANSPARENCIA', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186703'),
    (1190, 'SUB-1190', 'SBM2', '"LOS OFICIALES Y SUBOFICIALES TIENEN LOS MISMOS DERECHOS Y OPORTUNIDADES PARA LOS ASCENSOS EN SUS RESPECTIVOS GRADOS Y CATEGORÍAS, POR LO QUE QUEDA PROSCRITA TODA PRÁCTICA DE DISCRIMINACIÓN, PRIVILEGIO O PREFERENCIA". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE IGUALDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186706'),
    (1191, 'SUB-1191', 'SBM2', '"LOS PROCESOS DE ASCENSOS ESTÁN EXENTOS DE INTERÉS AJENO AL INSTITUCIONAL, POR LO QUE SE LLEVAN A CABO DE MANERA IMPARCIAL. LAS JUNTAS EVALUADORA, SELECTORA O REVISORA NO DEBEN TENER INTERÉS EN LOS RESULTADOS QUE SE ORIGINEN COMO CONSECUENCIA DE LOS PROCESOS DE ASCENSOS.". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE IMPARCIALIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186707'),
    (1192, 'SUB-1192', 'SBM2', '"LOS ASCENSOS EN LA CARRERA POLICIAL SE FUNDAMENTAN EN LOS MÉRITOS Y EN LAS CAPACIDADES PERSONALES, PROFESIONALES Y TÉCNICAS DEL PERSONAL CONSIGNADAS EN LA PRESENTE LEY." . EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE MERITOCRACIA', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186708'),
    (1193, 'SUB-1193', 'SBM2', '"LA APLICACIÓN DE LAS NORMAS ESTABLECIDAS SE REALIZA A TRAVÉS DE FACTORES, SUBFACTORES Y ELEMENTOS CLARAMENTE DEFINIDOS PARA LA EVALUACIÓN DE LAS APTITUDES PROFESIONALES, TÉCNICAS, DISCIPLINARIAS Y PSICOSOMÁTICAS". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE OBJETIVIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186709'),
    (1194, 'SUB-1194', 'SBM2', '. "SE FUNDAMENTA EN LA PUBLICACIÓN DE TODAS LAS ETAPAS DE LOS PROCESOS DE ASCENSOS. LOS RESULTADOS SE PUBLICAN DESPUÉS DE CADA EVALUACIÓN EN LA PÁGINA WEB Y MEDIANTE LOS CANALES O PLATAFORMAS DE COMUNICACIÓN DE LA POLICÍA NACIONAL DEL PERÚ (PNP)". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE TRANSPARENCIA', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186710'),
    (1195, 'SUB-1195', 'SBM2', '"LOS PROCESOS DE ASCENSOS SE LLEVAN A CABO EN CUMPLIMIENTO DE LAS NORMAS CONSTITUCIONALES, LAS DISPOSICIONES CONTENIDAS EN LA PRESENTE LEY Y OTRAS NORMAS LEGALES Y REGLAMENTARIAS SOBRE LA MATERIA". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE LEGALIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186711'),
    (1196, 'SUB-1196', 'SBM2', '"LOS CANDIDATOS E INTEGRANTES DE LAS JUNTAS QUE PARTICIPAN EN LOS PROCESOS DE ASCENSOS OBSERVAN LAS NORMAS ÉTICAS Y DE CONDUCTA, DEMOSTRANDO EN TODO MOMENTO HONESTIDAD, RESPETO Y TRANSPARENCIA EN LAS INTERACCIONES PERSONALES". EL ENUNCIADO CORRESPONDE A:', 'PRINCIPIO DE INTEGRIDAD', 'TÍTULO PRELIMINAR - ART. ÚNICO', '186712'),
    (1197, 'SUB-1197', 'SBM2', 'ESTABLECER LOS PRINCIPIOS, ETAPAS, REQUISITOS, APTITUDES Y PROCEDIMIENTOS PARA MATERIALIZAR LA ORGANIZACIÓN, EJECUCIÓN, CONTROL Y EVALUACIÓN DE LOS PROCESOS DE ASCENSOS DE LOS OFICIALES Y SUBOFICIALES QUE INTEGRAN LA POLICÍA NACIONAL DEL PERÚ (PNP), ASÍ COMO LAS COMPETENCIAS DE LAS JUNTAS CORRESPONDIENTES; CONSTITUYE:', 'EL OBJETO DE LA LEY 31873', 'ART. 1', '186713'),
    (1198, 'SUB-1198', 'SBM2', 'GARANTIZAR UNA LÍNEA DE CARRERA POLICIAL AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ (PNP) SUSTENTADA EN UN SISTEMA DE EVALUACIÓN DE MANERA MERITOCRÁTICA, EN CONSIDERACIÓN A SUS CAPACIDADES, CONOCIMIENTOS, HABILIDADES, DESEMPEÑO PROFESIONAL Y APTITUDES, EN ESTRICTA OBSERVANCIA DEL ORDENAMIENTO LEGAL VIGENTE; CONSTITUYE:', 'LA FINALIDAD DE LA LEY 31873', 'ART. 2', '186714'),
    (1199, 'SUB-1199', 'SBM2', 'ESTABLECER UN PROCEDIMIENTO OBJETIVO PARA CUANTIFICAR LOS FACTORES DE LA CARRERA POLICIAL, PARA LA PROMOCIÓN DE LOS OFICIALES Y SUBOFICIALES MÁS CALIFICADOS E IDÓNEOS AL GRADO INMEDIATO SUPERIOR EN LA POLICÍA NACIONAL DEL PERÚ (PNP); CONSTITUYE:', 'LA FINALIDAD DE LA LEY 31873', 'ART. 2', '186715'),
    (1200, 'SUB-1200', 'SBM2', 'ESTÁN COMPRENDIDOS EN EL ALCANCE DE LA PRESENTE LEY EL PERSONAL DE OFICIALES Y SUBOFICIALES DE ARMAS Y DE SERVICIOS QUE PERTENECEN A LA POLICÍA NACIONAL DEL PERÚ (PNP). EL ENUNCIADO ANTERIOR CONSTITUYE:', 'EL ALCANCE DE LA LEY 31873', 'ART. 3', '186716')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

